/* GENERADO por herramientas/generar-saber-juego.js: no editar a mano.
   Preguntas tipo Saber 11 de ChromaNom para el Juego (278). */
window.SABER_JUEGO=[{"t":"cadena_principal","c":"exp","af":"E1","ctx":"Dos estudiantes nombran el mismo alcano, CH₃−CH(C₂H₅)−CH₂−CH₃. Ana escribe «2-etilbutano» y Luis escribe «3-metilpentano».","q":"¿Quién tiene razón y por qué?","o":["Luis, porque la cadena más larga tiene 5 carbonos e incluye los del grupo etilo","Ana, porque el etilo es el sustituyente más grande y debe nombrarse","Ana, porque la cadena principal es la que aparece escrita en línea recta","Ambos, porque los dos nombres describen la misma molécula según la IUPAC"]},{"t":"cadena_principal","c":"uso","af":"I1","ctx":"Al numerar la cadena principal de un alcano ramificado hay que escoger por cuál extremo empezar.","q":"¿Cuál criterio se aplica PRIMERO?","o":["Dar los localizadores más bajos posibles al conjunto de sustituyentes","Dar el número más bajo al sustituyente que va primero en orden alfabético","Numerar siempre de izquierda a derecha, como está escrita la fórmula","Dar el número 1 al carbono que tiene el sustituyente más grande"]},{"t":"cadena_principal","c":"exp","af":"E1","ctx":"En el nombre 4-etil-2,2-dimetilhexano, el etilo se escribe antes que el metilo, aunque su localizador es mayor.","q":"¿Por qué se escribe en ese orden?","o":["Porque los sustituyentes se ordenan alfabéticamente y el prefijo di- no se tiene en cuenta","Porque el etilo tiene más carbonos que el metilo","Porque el sustituyente que aparece una sola vez siempre va primero","Porque los sustituyentes con localizador mayor se escriben primero"]},{"t":"cadena_principal","c":"ind","af":"N2","ctx":"Un grupo de estudiantes consultó los puntos de ebullición de tres isómeros de fórmula C₅H₁₂: pentano, 36 °C; 2-metilbutano, 28 °C; 2,2-dimetilpropano, 10 °C.","q":"¿Qué conclusión es coherente con estos datos?","o":["Para una misma fórmula molecular, a mayor ramificación menor punto de ebullición","A mayor masa molar, menor punto de ebullición","La ramificación no influye, porque los tres tienen la misma fórmula molecular","El punto de ebullición aumenta con el número de grupos metilo"]},{"t":"cadena_principal","c":"ind","af":"N3","ctx":"Una estudiante debe nombrar un alcano ramificado que está dibujado en zigzag y con las ramas hacia arriba y hacia abajo.","q":"¿Qué procedimiento le permite comprobar que escogió bien la cadena principal?","o":["Contar los carbonos de todos los caminos posibles entre extremos y escoger el más largo","Tomar la cadena horizontal tal como está dibujada","Escoger la cadena que empieza en el carbono de la izquierda","Contar solamente los carbonos que tienen tres hidrógenos"]},{"t":"cadena_principal","c":"uso","af":"I1","ctx":"Un compuesto se llama 3-etil-2,4-dimetilheptano.","q":"¿Cuántos carbonos tiene su cadena principal y cuántos tiene la molécula en total?","o":["7 en la cadena principal y 11 en total","7 en la cadena principal y 10 en total","11 en la cadena principal y 11 en total","9 en la cadena principal y 11 en total"]},{"t":"cadena_principal","c":"uso","af":"I2","ctx":"El ciclohexano es un disolvente industrial que se obtiene al hidrogenar el benceno.","q":"¿Cuál es el nombre IUPAC del compuesto que resulta de reemplazar un hidrógeno del ciclohexano por un grupo etilo?","o":["etilciclohexano","etilciclopentano","etilbenceno","cicloetilhexano"]},{"t":"cadena_principal","c":"exp","af":"E1","ctx":"En el nombre 4-isopropil-2-metilheptano (nombre tradicional aceptado; la IUPAC 2013 prefiere «propan-2-il» en lugar de «isopropil»), los sustituyentes se escriben en orden alfabético.","q":"¿Por qué «isopropil» se escribe antes que «metil»?","o":["Porque el prefijo iso- sí cuenta para el orden alfabético, e «i» va antes que «m»","Porque el isopropilo tiene más carbonos que el metilo","Porque el localizador 4 es mayor que el 2","Porque los sustituyentes ramificados siempre se escriben primero"]},{"t":"cadena_principal","c":"ind","af":"N2","ctx":"La planta de tratamiento de aguas residuales El Salitre, en Bogotá, captura el biogás que producen las bacterias al descomponer la materia orgánica sin oxígeno, y lo usa como fuente de energía.","q":"El biogás es rico en metano. ¿Qué evidencia confirmaría que el gas capturado es metano y no otro hidrocarburo?","o":["Quemar una muestra y comprobar que por cada mol de CO₂ se forman 2 moles de H₂O, como corresponde al CH₄","Medir el volumen de gas que se produce cada día y compararlo con el de otras plantas","Comprobar que el gas no tiene olor, porque el metano es el único gas inodoro","Medir la temperatura del tanque, porque solo el metano se forma a temperatura ambiente"]},{"t":"cadena_principal","c":"uso","af":"I1","ctx":"Un compañero escribió el nombre de un alcano de cuatro formas distintas: «2,3 dimetilbutano», «2-3-dimetilbutano», «2,3-dimetilbutano» y «2-3 dimetil-butano».","q":"¿Cuál de las cuatro cumple con la puntuación que usa la IUPAC (coma entre números, guion entre un número y una letra)?","o":["2,3-dimetilbutano","2,3 dimetilbutano","2-3-dimetilbutano","2-3 dimetil-butano"]},{"t":"cadena_principal","c":"exp","af":"E1","ctx":"En el nombre 2,2-dimetilbutano el localizador 2 se repite dos veces, uno para cada metilo.","q":"¿Por qué es necesario repetirlo en vez de escribir «2-dimetilbutano»?","o":["Porque cada sustituyente necesita su propio localizador, aunque los dos caigan en el mismo carbono","Porque el prefijo di- siempre exige dos números diferentes","Porque sin repetirlo el nombre no indicaría cuántos carbonos tiene la cadena principal","Porque la IUPAC prohíbe los localizadores repetidos"]},{"t":"cadena_principal","c":"uso","af":"I1","ctx":"En Colombia se venden gasolina corriente y gasolina extra; la extra tiene un índice de octano más alto. Ese índice compara la resistencia de un combustible a la autoignición con la del isooctano (índice 100) y la del heptano (índice 0).","q":"¿Qué significa que un combustible tenga un índice de octano más alto?","o":["Resiste mejor la autoignición (el «cascabeleo» del motor), de forma parecida al isooctano","Tiene más energía por litro, así que el carro rinde más kilómetros","Contiene más carbono y por eso produce más CO₂ al quemarse","Contiene una mayor proporción de octano lineal, el n-octano"]},{"t":"cadena_principal","c":"ind","af":"N3","ctx":"Un estudiante afirma: «3-etilpentano y 3-metilhexano son el mismo compuesto, porque los dos tienen 7 carbonos en total».","q":"¿Cómo se puede comprobar si esa afirmación es correcta?","o":["Dibujando la estructura completa de cada nombre y comparando cómo están unidos los átomos, no solo el total de carbonos","Contando solamente los carbonos de la cadena principal de cada nombre y comparando esos dos números","Buscando los dos nombres en una tabla de alcanos comunes y viendo si aparecen en la misma fila","Comparando el punto de ebullición de los dos líquidos, sin necesidad de dibujar las estructuras"]},{"t":"cadena_principal","c":"exp","af":"E1","ctx":"La IUPAC recomienda nombres sistemáticos (como butano) en vez de nombres triviales o comerciales que cambian de una región a otra.","q":"¿Cuál es la principal ventaja de tener un sistema de nomenclatura único e internacional?","o":["Permite que cualquier químico, en cualquier país, identifique sin ambigüedad la misma sustancia a partir de su nombre","Hace que los nombres sean más cortos y fáciles de memorizar para los estudiantes de todo el mundo","Evita que las sustancias reaccionen entre sí cuando se almacenan juntas en el laboratorio","Elimina por completo la necesidad de dibujar las estructuras de las moléculas orgánicas"]},{"t":"cadena_principal","c":"exp","af":"E1","ctx":"Un heptano tiene sustituyentes metilo en dos carbonos y etilo en uno. Numerando por un extremo, los localizadores quedan en {2,3,6}; numerando por el otro extremo, en {2,5,6}.","q":"¿Cuál conjunto de localizadores es el correcto, según la regla de la IUPAC?","o":["{2,3,6}, porque en el primer punto de diferencia (la segunda posición) 3 es menor que 5","{2,5,6}, porque la suma de sus números es mayor y eso indica la numeración correcta","Cualquiera de los dos, porque ambos conjuntos empiezan con el localizador 2","{2,3,6}, porque es el que deja el número más alto, 6, en la última posición"]},{"t":"cadena_principal","c":"exp","af":"E1","ctx":"Dos cadenas posibles de un mismo alcano ramificado tienen ambas 6 carbonos de longitud, pero una de ellas pasa por un carbono que tiene dos ramificaciones y la otra no pasa por ningún carbono ramificado.","q":"Según la regla de desempate de la IUPAC, ¿cuál de las dos se escoge como cadena principal?","o":["La que tiene más sustituyentes, aunque las dos tengan la misma longitud","La que no tiene ningún sustituyente, porque es más sencilla de nombrar","Ninguna: si hay empate en longitud, la molécula no se puede nombrar","La que aparece dibujada en línea horizontal"]},{"t":"cadena_principal","c":"ind","af":"N2","ctx":"Un estudiante consultó la energía que libera 1 g de tres hidrocarburos al quemarse: metano, 55 kJ; propano, 50 kJ; octano, 48 kJ.","q":"¿Qué conclusión es coherente con estos datos?","o":["Por gramo, la energía liberada disminuye un poco a medida que la cadena es más larga","La energía liberada por gramo no depende del hidrocarburo que se queme","El octano libera más energía por gramo que el metano porque es más grande","La energía por gramo aumenta a medida que la cadena es más larga"]},{"t":"cadena_principal","c":"ind","af":"N1","ctx":"Una estudiante afirma que el carbono forma cadenas largas porque hace cuatro enlaces y puede unirse con otros átomos de carbono.","q":"¿Qué evidencia apoya mejor su afirmación?","o":["Que existen alcanos estables de más de 30 carbonos, como los de la parafina, con cadenas de enlaces C−C","Que el carbón vegetal es negro porque tiene cadenas muy largas de carbono","Que el diamante es muy duro porque sus carbonos forman cadenas lineales","Que el CO₂ es un gas porque el carbono no se une con otros carbonos"]},{"t":"cadena_principal","c":"ind","af":"N4","ctx":"Un estudiante predice que, entre alcanos lineales, a más carbonos mayor densidad del líquido. Consulta: pentano 0,626 g/mL; hexano 0,659; heptano 0,684; octano 0,703.","q":"¿Los datos apoyan su predicción?","o":["Sí: la densidad aumenta poco a poco a medida que la cadena es más larga","No: la densidad cambia muy poco, así que la longitud de la cadena no influye","Sí, pero solo porque el octano es el único que tiene ocho carbonos","No: para saberlo habría que medir el punto de ebullición y no la densidad"]},{"t":"cadena_principal","c":"ind","af":"N2","ctx":"Al quemar por completo 1 mol de tres alcanos se midió el CO₂ producido: metano, 1 mol; propano, 3 mol; pentano, 5 mol.","q":"¿Qué conclusión se apoya en los datos?","o":["Cada carbono de la cadena termina formando una molécula de CO₂","Los alcanos producen siempre la misma cantidad de CO₂ al quemarse","El CO₂ producido depende de los hidrógenos y no de los carbonos","Los alcanos más largos producen menos CO₂ por mol que los cortos"]},{"t":"alcanos","c":"uso","af":"I1","ctx":"El gas de las pipetas (GLP) que se usa en muchas cocinas colombianas es principalmente una mezcla de propano y butano.","q":"¿Cuál es la fórmula molecular del butano?","o":["C₄H₁₀","C₄H₈","C₄H₆","C₃H₈"]},{"t":"alcanos","c":"uso","af":"I1","ctx":"Los alcanos de cadena abierta cumplen la fórmula general CₙH₂ₙ₊₂.","q":"¿Cuál de los siguientes compuestos NO cumple esa fórmula?","o":["ciclohexano, C₆H₁₂","hexano, C₆H₁₄","propano, C₃H₈","decano, C₁₀H₂₂"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"La combustión completa del metano es CH₄ + 2 O₂ → CO₂ + 2 H₂O. Cuando la estufa recibe poco aire, la llama se vuelve amarilla y aparece hollín en las ollas.","q":"¿Qué explica este cambio?","o":["Con poco oxígeno la combustión es incompleta y se forman carbono (hollín) y monóxido de carbono","Con poco oxígeno el metano se convierte en un alqueno que arde con llama amarilla","Con poco oxígeno se produce más CO₂ y más agua","El hollín proviene del nitrógeno del aire que no reaccionó"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"El metano reacciona con cloro solo en presencia de luz ultravioleta (hν) o calor, y se forman CH₃Cl y HCl.","q":"¿Cuál es la función de la luz en esta reacción?","o":["Romper de forma homolítica el enlace Cl−Cl para formar radicales cloro","Romper el enlace C−H para formar los iones H⁺ y CH₃⁻","Volver polar al metano para que actúe como nucleófilo","Formar un doble enlace en el metano para que ocurra una adición"]},{"t":"alcanos","c":"ind","af":"N2","ctx":"Se registraron los puntos de ebullición de varios alcanos: metano, −162 °C; etano, −89 °C; propano, −42 °C; butano, −1 °C.","q":"Si la tendencia continúa, ¿qué se espera para el pentano?","o":["Un valor mayor que −1 °C, porque la cadena es más larga y las fuerzas de London aumentan","Un valor menor que −162 °C, porque tiene más hidrógenos","Un valor entre −89 °C y −42 °C, porque el pentano es un isómero del butano","El mismo valor del butano, porque ambos son alcanos"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"Colombia produce gas natural en La Guajira y en el piedemonte llanero. Las fugas de metano en pozos y tuberías preocupan aunque no haya incendio.","q":"¿Por qué una fuga de metano es un problema ambiental?","o":["Porque el metano es un gas de efecto invernadero más potente que el CO₂ por molécula","Porque el metano destruye la capa de ozono igual que los CFC","Porque el metano reacciona con la lluvia y forma ácido sulfúrico","Porque el metano es un sólido que se acumula en los suelos"]},{"t":"alcanos","c":"uso","af":"I1","ctx":"Todos los átomos de carbono del propano están unidos solo por enlaces sencillos.","q":"¿Qué hibridación y qué geometría tienen esos carbonos?","o":["sp³, tetraédrica, con ángulos cercanos a 109,5°","sp², trigonal plana, con ángulos de 120°","sp, lineal, con ángulos de 180°","sp³, plana cuadrada, con ángulos de 90°"]},{"t":"alcanos","c":"uso","af":"I1","ctx":"La combustión completa del propano (el gas de muchas pipetas) consume oxígeno y produce dióxido de carbono y agua.","q":"¿Cuál es la ecuación balanceada de esa combustión?","o":["C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O","C₃H₈ + 3 O₂ → 3 CO₂ + 4 H₂O","C₃H₈ + 5 O₂ → 3 CO + 4 H₂O","C₃H₈ + O₂ → CO₂ + H₂O"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"El gas natural y el GLP son inodoros en su estado puro. Por seguridad, las empresas de gas les agregan un compuesto con azufre (un mercaptano) de olor fuerte y desagradable.","q":"¿Cuál es la razón principal para agregar ese compuesto?","o":["Permite detectar una fuga por el olfato, antes de que el gas acumulado sea un riesgo de explosión","Hace que el gas arda con una llama más azul y caliente en la estufa","Evita que el gas se vuelva líquido cuando está dentro del cilindro","Le da a cada marca un olor distinto para que el cliente la reconozca"]},{"t":"alcanos","c":"uso","af":"I1","ctx":"Los cicloalcanos (anillos saturados de carbono) cumplen la fórmula general CₙH₂ₙ, a diferencia de los alcanos de cadena abierta (CₙH₂ₙ₊₂).","q":"¿Cuál es la fórmula molecular del ciclopentano?","o":["C₅H₁₀","C₅H₁₂","C₅H₈","C₄H₁₀"]},{"t":"alcanos","c":"exp","af":"E3","ctx":"A temperatura ambiente, el metano es un gas, el hexano es un líquido y la parafina (una mezcla de alcanos de cadena muy larga) es un sólido blando.","q":"¿Qué explica esta diferencia de estado físico entre alcanos?","o":["A mayor longitud de cadena, mayores son las fuerzas de London entre las moléculas, lo que eleva el punto de fusión y de ebullición","Las cadenas largas tienen enlaces C−C más fuertes que las cadenas cortas, así que sus moléculas se separan con más dificultad","Los alcanos de cadena larga tienen carga eléctrica y por eso sus moléculas se atraen con fuerza entre sí","Las moléculas pequeñas pesan más que las grandes y por eso escapan como gas a temperatura ambiente"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"La vaselina que se usa en cosmética y primeros auxilios es una mezcla de alcanos sólidos de cadena larga (20 a 40 carbonos), obtenidos del petróleo.","q":"¿Por qué los alcanos son tan poco reactivos frente a la piel y otras sustancias?","o":["Porque sus enlaces C−C y C−H son poco polares y muy estables, así que no reaccionan con facilidad","Porque los alcanos son ácidos débiles que no afectan la piel","Porque los alcanos tienen dobles enlaces que los hacen inertes","Porque los alcanos se disuelven muy bien en agua y no quedan sobre la piel"]},{"t":"alcanos","c":"uso","af":"I1","ctx":"El 2,2,3-trimetilbutano es un alcano ramificado: su cadena principal de 4 carbonos (butano) lleva tres grupos metilo.","q":"¿Cuál es su fórmula molecular?","o":["C₇H₁₆","C₇H₁₄","C₇H₁₈","C₄H₁₀"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"El propano de las pipetas se guarda líquido dentro del cilindro, a presión, y se convierte en gas apenas sale por la válvula.","q":"¿Por qué el propano puede licuarse con solo aumentar la presión, sin necesidad de enfriarlo mucho?","o":["Porque a temperatura ambiente bastan unas 8 atm para que sus fuerzas de London mantengan las moléculas unidas como líquido","Porque el propano es un compuesto iónico que se compacta fácilmente cuando aumenta la presión","Porque la presión rompe los enlaces C−H del propano y lo convierte en un líquido distinto","Porque el propano reacciona con el aire del cilindro al comprimirse y forma un líquido"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"Al quemar 1 mol de metano se liberan cerca de 890 kJ; al quemar 1 mol de octano se liberan cerca de 5 470 kJ.","q":"¿Qué explica que el octano libere mucha más energía por mol que el metano?","o":["El octano tiene más átomos de C y H por molécula, que al oxidarse forman muchos más enlaces en CO₂ y H₂O","El metano no es realmente un combustible, solo un gas que arde con dificultad","El octano tiene enlaces iónicos que el metano no tiene y que guardan más energía","En realidad el metano libera más energía por mol, porque su molécula es más simple"]},{"t":"alcanos","c":"ind","af":"N2","ctx":"Un estudiante quiere comprobar si el gas de una fuga en su cocina es GLP (propano y butano) o metano de la red de gas natural.","q":"¿Qué dato sería más útil para decidirlo, sin necesidad de un laboratorio?","o":["Observar si el gas se acumula cerca del piso o sube: el GLP es más denso que el aire y el metano, menos","El olor del gas, porque solo el GLP lleva odorizante y el gas natural no huele a nada","El precio que pagó por el servicio de gas, porque el metano es más caro que el GLP","La temperatura de la cocina en el momento de la fuga, porque el GLP enfría el aire"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"Las fugas de GLP son peligrosas en espacios cerrados porque el gas, al ser más denso que el aire, tiende a acumularse cerca del piso.","q":"¿Qué recomendación de seguridad se deriva directamente de esta propiedad?","o":["Ventilar por la parte baja del espacio y evitar generar chispas cerca del piso si se sospecha una fuga","Abrir únicamente las ventanas más altas, porque el gas sube y sale por arriba","Guardar el cilindro siempre en un lugar elevado, lejos del piso de la cocina","Usar el gas solamente en espacios cerrados para que no se disperse por la casa"]},{"t":"alcanos","c":"uso","af":"I2","ctx":"En las refinerías, el craqueo (cracking) rompe moléculas largas de alcanos del petróleo, con calor y catalizadores, para obtener gasolina y otros combustibles más ligeros.","q":"¿Qué tipo de productos se obtienen al romper una cadena larga de alcano por craqueo?","o":["Una mezcla de alcanos y alquenos más pequeños, porque al romper un enlace C−C sobra un carbono con un doble enlace","Solo alcanos más pequeños, porque el craqueo rompe únicamente los enlaces C−H de la cadena","Solo CO₂ y agua, igual que en la combustión, porque se usa calor para romper la cadena","Un solo alqueno muy grande, sin ningún alcano, porque la cadena pierde todos sus hidrógenos"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"A diferencia de un doble enlace, un enlace sencillo C−C como los del propano puede girar libremente sobre su eje sin romperse.","q":"¿Por qué un enlace sencillo (σ) permite esta rotación?","o":["Porque es un solapamiento simétrico alrededor del eje que une los dos núcleos, así que girar no cambia el solapamiento de los orbitales","Porque el enlace sencillo es mucho más débil que uno doble y se rompe y se vuelve a formar constantemente al girar","Porque los átomos de carbono no tienen masa suficiente para resistir el giro de un extremo de la molécula","Porque en los alcanos los carbonos no comparten electrones y quedan libres para girar sin restricción"]},{"t":"alcanos","c":"exp","af":"E1","ctx":"Al derramarse petróleo crudo (una mezcla de hidrocarburos, en su mayoría alcanos) en el mar, la mancha flota y se extiende sobre la superficie del agua, sin mezclarse con ella.","q":"¿Qué dos propiedades de los alcanos explican este comportamiento?","o":["Son apolares (no se mezclan con el agua, que es polar) y menos densos que el agua","Son muy densos y se hunden en el fondo del mar","Son polares y forman puentes de hidrógeno con el agua","Son compuestos iónicos que flotan por repulsión eléctrica"]},{"t":"alcanos","c":"ind","af":"N4","ctx":"Puntos de ebullición de los primeros alcanos: metano, −162 °C; etano, −89 °C; propano, −42 °C; butano, −1 °C.","q":"Si el patrón se mantiene, ¿qué valor es más probable para el pentano?","o":["Cerca de 36 °C","Cerca de −50 °C","Cerca de −1 °C","Cerca de 200 °C"]},{"t":"alcanos","c":"ind","af":"N3","ctx":"Para comparar qué tan rápido se evaporan el hexano y el decano, un estudiante pone 1 mL de cada uno en un vidrio de reloj y mide el tiempo que tardan en desaparecer.","q":"¿Qué condiciones debe controlar para que la comparación sea válida?","o":["Que los dos líquidos estén a la misma temperatura, con la misma superficie y la misma ventilación","Que los dos líquidos tengan colores diferentes para distinguirlos","Usar más cantidad de decano porque se evapora más despacio","Poner el hexano al sol y el decano a la sombra para acelerar la prueba"]},{"t":"alcanos","c":"ind","af":"N3","ctx":"Una estudiante quiere saber si los alcanos se disuelven en agua o en aceite. Tiene hexano, agua, aceite de cocina y tubos de ensayo.","q":"¿Qué procedimiento es adecuado?","o":["Agregar la misma cantidad de hexano a tubos con igual volumen de agua y de aceite, y observar si se forman capas","Agregar hexano solo al agua y suponer que con el aceite pasaría lo contrario","Calentar el hexano hasta que hierva y ver si se mezcla con el vapor del agua","Agregar hexano al agua y al aceite en cantidades distintas y observar el color"]},{"t":"alcanos","c":"ind","af":"N2","ctx":"Se midió la viscosidad de tres alcanos a 25 °C: hexano 0,30; decano 0,85; hexadecano 3,0 (en mPa·s).","q":"¿Qué conclusión es coherente con los datos?","o":["A cadena más larga, el líquido fluye con más dificultad","A cadena más larga, el líquido fluye con más facilidad","La viscosidad no depende de la longitud de la cadena","El hexano es el más viscoso porque tiene menos carbonos"]},{"t":"alcanos","c":"ind","af":"N4","ctx":"Una estudiante consultó el punto de ebullición de los ocho primeros alcanos de cadena lineal, del metano al octano.","q":"¿Qué relación muestra la gráfica y cómo se explica?","o":["Aumenta con el número de carbonos porque crecen las fuerzas de London","Disminuye con el número de carbonos porque la cadena se rompe más fácil","Aumenta porque los alcanos largos forman puentes de hidrógeno","No cambia porque todos los alcanos son apolares"],"exp":"El punto de ebullición sube de −162 °C (metano) a 126 °C (octano). Las cadenas más largas tienen más superficie de contacto y fuerzas de London más intensas. Los alcanos son apolares y no forman puentes de hidrógeno.","graf":{"tipo":"lin","x":["1","2","3","4","5","6","7","8"],"y":[-162,-89,-42,0,36,69,98,126],"ymin":-200,"ex":"Número de carbonos","ey":"Punto de ebullición (°C)"}},{"t":"alquinos","c":"uso","af":"I1","ctx":"El propino es el alquino de tres carbonos.","q":"¿Cuál es su fórmula molecular?","o":["C₃H₄","C₃H₆","C₃H₈","C₃H₂"]},{"t":"alquenos","c":"ind","af":"N2","ctx":"Para diferenciar hexano de hex-1-eno, una estudiante agrega unas gotas de agua de bromo (de color naranja) a cada muestra, a temperatura ambiente y sin luz intensa.","q":"¿Qué resultado permite identificar el alqueno?","o":["El tubo con hex-1-eno pierde el color naranja porque el Br₂ se adiciona al doble enlace","El tubo con hexano pierde el color porque los alcanos reaccionan rápido con Br₂ sin luz","Ambos tubos pierden el color por igual, así que la prueba no sirve","El tubo con hex-1-eno se vuelve azul porque se forma un ácido"]},{"t":"alquenos","c":"uso","af":"I2","ctx":"En el compuesto CH₂=CH−CH₂−C≡CH, numerando desde cualquiera de los dos extremos, los enlaces múltiples quedan en las posiciones 1 y 4.","q":"Según la IUPAC, ¿cuál es su nombre?","o":["pent-1-en-4-ino","pent-4-en-1-ino","pent-1-in-4-eno","penta-1,4-dieno"]},{"t":"alquinos","c":"exp","af":"E1","ctx":"La soldadura autógena usa una llama de acetileno (etino, CH≡CH) y oxígeno, que alcanza hasta 3 100 °C, mucho más que la llama del gas propano.","q":"¿Qué ayuda a explicar que su llama con oxígeno sea tan caliente?","o":["El acetileno es una molécula de alta energía: su formación absorbe energía, que se libera al quemarse","El acetileno ya contiene oxígeno en su propia molécula y no necesita el del aire","El acetileno es un compuesto iónico con mucha energía de red que se libera al arder","El acetileno tiene más átomos de carbono que el propano y por eso arde más caliente"]},{"t":"alquenos","c":"uso","af":"I1","ctx":"El buta-1,3-dieno es la materia prima para fabricar caucho sintético, como el de las llantas.","q":"¿Cuál es su fórmula estructural?","o":["CH₂=CH−CH=CH₂","CH₂=CH−CH₂−CH₃","CH≡C−CH₂−CH₃","CH₃−CH=CH−CH₃"]},{"t":"alquenos","c":"uso","af":"I1","ctx":"El caucho natural, que se extrae de árboles cultivados también en el Caquetá y el Meta, es un polímero del isopreno (2-metilbuta-1,3-dieno).","q":"¿Cuántos dobles enlaces tiene cada unidad de isopreno antes de polimerizarse?","o":["Dos","Uno","Tres","Ninguno, porque el isopreno es un alcano"]},{"t":"alquenos","c":"uso","af":"I1","ctx":"Para producir margarina a partir de aceites vegetales líquidos, la industria hace pasar H₂ gaseoso por el aceite caliente, con un catalizador de níquel.","q":"¿Qué cambio estructural ocurre en los ácidos grasos del aceite durante este proceso?","o":["Los dobles enlaces C=C se convierten en enlaces sencillos C−C, por adición de hidrógeno","Los dobles enlaces C=C se transforman en triples enlaces al recibir el hidrógeno","Se forman nuevos anillos aromáticos dentro de la cadena del ácido graso","Los ácidos grasos pierden átomos de carbono, que salen como metano"]},{"t":"alquinos","c":"uso","af":"I1","ctx":"En el etino (acetileno), cada carbono del triple enlace tiene hibridación sp y está unido a otros dos átomos.","q":"¿Qué geometría tienen esos carbonos?","o":["Lineal, con ángulos de 180°","Tetraédrica, con ángulos de 109,5°","Trigonal plana, con ángulos de 120°","Piramidal, con ángulos de 107°"]},{"t":"alquenos","c":"uso","af":"I1","ctx":"El polipropileno, usado en empaques de alimentos y tapas de botellas, se fabrica uniendo muchas moléculas de propeno.","q":"¿Cuál es la fórmula molecular del propeno, el monómero de este plástico?","o":["C₃H₆","C₃H₈","C₃H₄","C₂H₄"]},{"t":"alquinos","c":"ind","af":"N2","ctx":"Un alqueno y un alquino, cada uno con un solo enlace múltiple y la misma cantidad de carbonos, reaccionan por separado con agua de bromo (Br₂) en exceso.","q":"¿Qué diferencia debería observarse entre los dos?","o":["El alquino consume el doble de Br₂ por mol que el alqueno, porque tiene dos enlaces π que pueden reaccionar con el Br₂","Los dos consumen la misma cantidad de Br₂ por mol, porque cada uno tiene un solo enlace múltiple en su molécula","El alqueno consume más Br₂ que el alquino, porque su doble enlace es más reactivo que el triple","Ninguno de los dos reacciona con el Br₂ si no hay luz ultravioleta que rompa los enlaces"]},{"t":"alquenos","c":"uso","af":"I1","ctx":"El eteno no solo se usa para madurar frutas: también es la materia prima más consumida por la industria petroquímica para fabricar plásticos.","q":"¿Qué polímero de uso masivo (bolsas, envases) se obtiene al unir muchas moléculas de eteno?","o":["Polietileno","Poliestireno","PVC (policloruro de vinilo)","Nailon"]},{"t":"alquenos","c":"uso","af":"I2","ctx":"El pent-2-eno puede existir como dos isómeros distintos, cis y trans, porque su doble enlace no puede girar y cada carbono del C=C tiene dos grupos diferentes.","q":"¿Qué nombre recibe este tipo de isomería?","o":["Isomería geométrica (cis/trans)","Isomería de cadena","Isomería de función","Isomería de posición"]},{"t":"alquenos","c":"uso","af":"I1","ctx":"El propeno (gas usado en la fabricación de polipropileno) también puede quemarse completamente con oxígeno, igual que un alcano.","q":"¿Cuál es la ecuación balanceada de su combustión completa?","o":["2 C₃H₆ + 9 O₂ → 6 CO₂ + 6 H₂O","C₃H₆ + 3 O₂ → 3 CO₂ + 3 H₂O","2 C₃H₆ + 9 O₂ → 6 CO + 6 H₂O","C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O"]},{"t":"alquenos","c":"uso","af":"I1","ctx":"El but-2-ino reacciona con exceso de HBr.","q":"¿Cuál es el producto final, aplicando la adición de HBr dos veces?","o":["2,2-dibromobutano","1,1-dibromobutano","2,3-dibromobutano","2-bromobut-2-eno"]},{"t":"alquenos","c":"ind","af":"N2","ctx":"Al agregar agua de bromo (de color naranja) a tres líquidos, el ciclohexano y el hexano no cambian de color, y el ciclohexeno se decolora al instante.","q":"¿Qué conclusión es válida?","o":["Solo el ciclohexeno tiene un doble enlace C=C que reacciona con el bromo","Los tres líquidos son alquenos, pero el ciclohexeno reacciona más rápido","El hexano tiene un doble enlace que reacciona solo con calor","El bromo reacciona con cualquier hidrocarburo si se espera lo suficiente"]},{"t":"alquenos","c":"ind","af":"N3","ctx":"Un estudiante predice que el aceite de oliva tiene más dobles enlaces que la mantequilla. Tiene una solución de yodo que se decolora al reaccionar con los dobles enlaces: cuantos más dobles enlaces, más gotas se decoloran.","q":"¿Qué procedimiento le permite evaluar su predicción?","o":["Agregar gota a gota la solución de yodo a masas iguales de aceite y de mantequilla, y comparar cuántas gotas se decoloran en cada una","Calentar el aceite y la mantequilla hasta que hiervan y comparar cuál de los dos humea más en el recipiente","Probar la solución de yodo solo con el aceite y comparar el resultado con lo que dice la etiqueta del frasco","Comparar el color y el olor del aceite y de la mantequilla antes de agregar el yodo a cualquiera de los dos"]},{"t":"alquenos","c":"ind","af":"N2","ctx":"Se agregó permanganato de potasio violeta a tres líquidos: con ciclohexano el color no cambió; con hex-1-eno y con ciclohexeno el violeta desapareció y se formó un sólido café.","q":"¿Qué conclusión se apoya en las observaciones?","o":["Los dos líquidos que reaccionaron tienen enlaces dobles C=C","Los tres líquidos tienen enlaces dobles, pero uno reacciona lento","El ciclohexano tiene un doble enlace que no reacciona con el permanganato","El permanganato reacciona con cualquier hidrocarburo que tenga un anillo"]},{"t":"alquenos","c":"ind","af":"N3","ctx":"Un estudiante quiere saber si la luz acelera la reacción del bromo con un alqueno. Tiene dos tubos iguales con la misma mezcla.","q":"¿Qué diseño es adecuado?","o":["Dejar un tubo a la luz y otro cubierto, a la misma temperatura, y medir cuánto tarda en perderse el color","Dejar los dos tubos a la luz y agregar más bromo a uno de ellos","Cubrir un tubo y calentar el otro, para que la reacción ocurra más rápido","Usar un alqueno distinto en cada tubo y dejarlos los dos a la luz"]},{"t":"alquenos","c":"ind","af":"N4","ctx":"Una estudiante predice que los isómeros cis y trans del but-2-eno tienen distinto punto de ebullición. Consulta: cis, 4 °C; trans, 1 °C.","q":"¿Qué se puede decir de su predicción?","o":["Los datos la apoyan: aunque la diferencia es pequeña, los valores son distintos","Los datos la refutan: los dos son gases a temperatura ambiente","No se puede evaluar, porque los isómeros siempre tienen las mismas propiedades","Los datos la apoyan solo si el isómero trans hirviera a mayor temperatura"]},{"t":"alquenos","c":"ind","af":"N1","ctx":"Markovnikov propuso en 1870 su regla después de estudiar muchas adiciones de HX a alquenos distintos y notar que el producto principal seguía el mismo patrón.","q":"¿Cómo se llegó a esa regla?","o":["Generalizando un patrón que se repetía en muchos resultados experimentales","Haciendo una sola reacción y suponiendo que todas las demás serían iguales","Calculando la energía de los enlaces con computadores modernos","Copiando una regla que ya se usaba para los alcanos"]},{"t":"alquenos","c":"ind","af":"N2","ctx":"Un grupo agitó tres líquidos incoloros con agua de bromo, que es de color naranja, y registró el color final. Los líquidos eran ciclohexeno, ciclohexano y hexano.","q":"¿Qué conclusión es válida con estos resultados?","o":["Solo la muestra 1 tiene dobles enlaces entre carbonos","Las tres muestras tienen dobles enlaces, porque cambiaron de color","Las muestras 2 y 3 tienen dobles enlaces, porque no reaccionaron","No se puede concluir nada sin conocer la masa de cada muestra"],"tabla":[["Muestra","Color tras agitar con agua de bromo"],["1","Incoloro"],["2","Naranja"],["3","Naranja"]],"exp":"El agua de bromo se decolora cuando el Br₂ se adiciona a un doble enlace: solo la muestra 1 (ciclohexeno) cambió. Las muestras 2 y 3, saturadas, no reaccionaron y conservan el color naranja."},{"t":"benceno","c":"uso","af":"I2","ctx":"El xileno, usado como solvente en laboratorios, es una mezcla de dimetilbencenos.","q":"¿Qué nombre IUPAC corresponde al isómero en el que los dos metilos están en carbonos vecinos del anillo?","o":["1,2-dimetilbenceno","1,3-dimetilbenceno","1,4-dimetilbenceno","2,3-dimetilbenceno"]},{"t":"benceno","c":"exp","af":"E1","ctx":"En la fórmula de Kekulé el benceno se dibuja con tres dobles enlaces; sin embargo, no reacciona como un alqueno.","q":"¿Por qué el benceno da sustitución electrofílica y no adición?","o":["Porque sus 6 electrones π están deslocalizados en el anillo y la sustitución conserva esa estabilidad","Porque el benceno no tiene electrones π y no puede dar adición","Porque los carbonos del benceno tienen hibridación sp³ como los alcanos","Porque la adición rompería enlaces C−H, que son los más fuertes del anillo"]},{"t":"benceno","c":"uso","af":"I1","ctx":"Un taller de pintura usa tíner, que puede contener tolueno. Las normas de salud ocupacional limitan estrictamente el benceno en los solventes.","q":"¿Cuál es la razón principal de esa restricción?","o":["El benceno es cancerígeno (se asocia con leucemia) y es volátil, por lo que se inhala con facilidad","El benceno no se evapora y se acumula en la ropa y la piel de los trabajadores","El benceno es un ácido fuerte que quema la piel al contacto con la pintura","El benceno reacciona con el aire del taller y produce grandes cantidades de ozono"]},{"t":"benceno","c":"ind","af":"N3","ctx":"Un libro de texto reporta un experimento para comprobar la hipótesis «el benceno no se comporta como un alqueno» (el benceno es cancerígeno y no se usa en el colegio): se agrega agua de bromo, sin catalizador, a un tubo con ciclohexeno y a otro con benceno, y se observa la mezcla completa.","q":"¿Qué resultado apoya la hipótesis?","o":["El ciclohexeno decolora el agua de bromo y el benceno no","Ambos decoloran el agua de bromo de inmediato","Solo el benceno decolora el agua de bromo","Ninguno reacciona, porque los dos son compuestos cíclicos"]},{"t":"benceno","c":"uso","af":"I1","ctx":"El 1,4-diclorobenceno se usa en algunas bolas antipolillas.","q":"En la nomenclatura tradicional, ¿qué posición relativa tienen sus dos cloros?","o":["para","orto","meta","alfa"]},{"t":"benceno","c":"exp","af":"E1","ctx":"La nitración del benceno se hace con una mezcla de HNO₃ y H₂SO₄ concentrados.","q":"¿Cuál es el papel del H₂SO₄?","o":["Ayuda a formar el ion nitronio (NO₂⁺), que es el electrófilo que ataca el anillo","Aporta el grupo −SO₃H que queda en el producto final","Neutraliza el ácido nítrico para que no reaccione","Rompe el anillo bencénico para que se adicione el grupo NO₂"]},{"t":"benceno","c":"uso","af":"I1","ctx":"La naftalina que se usa contra las polillas está hecha de naftaleno, un hidrocarburo aromático formado por dos anillos bencénicos fusionados (C₁₀H₈).","q":"¿Qué tienen en común el naftaleno y el benceno?","o":["Ambos tienen anillos con electrones π deslocalizados, que les dan una estabilidad extra","Ambos son alcanos saturados, sin ningún doble enlace en sus anillos","Ambos tienen un solo átomo de carbono por cada anillo de la molécula","Ninguno de los dos tiene carbonos sp², porque sus anillos son cerrados"]},{"t":"benceno","c":"exp","af":"E1","ctx":"Para bromar el benceno (sustituir un H por Br) se necesita Br₂ junto con un catalizador como FeBr₃; sin el catalizador, la reacción prácticamente no ocurre.","q":"¿Cuál es la función del FeBr₃ en esta reacción?","o":["Ayuda a polarizar el Br₂ y a generar un electrófilo lo bastante fuerte para atacar el anillo aromático","Se incorpora al producto final, sustituyendo uno de los hidrógenos del anillo de benceno","Reduce el benceno a ciclohexano para que el bromo pueda sumarse a la molécula","Rompe el anillo aromático para que el bromo se una a los extremos de la cadena"]},{"t":"benceno","c":"uso","af":"I1","ctx":"El icopor (poliestireno expandido), usado en empaques y vasos desechables, se fabrica a partir del estireno (feniletileno).","q":"¿Cuál es la fórmula estructural del estireno?","o":["C₆H₅−CH=CH₂","C₆H₅−CH₂−CH₃","C₆H₅−CH₃","C₆H₅−C≡CH"]},{"t":"benceno","c":"uso","af":"I1","ctx":"La aspirina (ácido acetilsalicílico) tiene un anillo aromático con dos grupos unidos a carbonos vecinos del anillo: uno éster y uno ácido carboxílico.","q":"¿Qué posición relativa (nomenclatura tradicional) tienen dos sustituyentes en carbonos vecinos de un anillo aromático?","o":["orto","meta","para","alfa"]},{"t":"benceno","c":"exp","af":"E1","ctx":"El benceno se dibuja con tres dobles enlaces «alternados» (fórmula de Kekulé), pero en la molécula real los 6 enlaces C−C miden exactamente lo mismo, un valor intermedio entre un enlace sencillo y uno doble.","q":"¿Qué evidencia da este dato sobre la estructura real del benceno?","o":["Los electrones π no están fijos en enlaces dobles alternados, sino deslocalizados por igual en todo el anillo","El benceno tiene en realidad seis enlaces sencillos, sin ningún doble enlace","El benceno cambia de estructura cada cierto tiempo, alternando entre dos formas distintas","Los seis carbonos del benceno no están todos en el mismo plano"]},{"t":"benceno","c":"ind","af":"N2","ctx":"Un libro de texto reporta que, para distinguir el ciclohexeno del benceno, se agrega KMnO₄ diluido y frío (de color violeta) a cada uno, a la misma temperatura.","q":"¿Qué resultado es coherente con el comportamiento esperado de cada compuesto?","o":["El ciclohexeno decolora el KMnO₄ porque su doble enlace se oxida; el benceno no reacciona en esas condiciones","El benceno decolora el KMnO₄ porque tiene tres dobles enlaces; el ciclohexeno, no","Ambos decoloran el KMnO₄ con la misma rapidez, porque los dos tienen enlaces C=C","Ninguno reacciona, porque los dos son hidrocarburos y no se oxidan"]},{"t":"benceno","c":"uso","af":"I2","ctx":"El 1,3-diclorobenceno y el 1,4-diclorobenceno son dos de los tres isómeros posibles del diclorobenceno (el anillo numerado del 1 al 6).","q":"¿Cuál es el nombre IUPAC correcto del tercer isómero?","o":["1,2-diclorobenceno","1,5-diclorobenceno","2,3-diclorobenceno","1,6-diclorobenceno"]},{"t":"benceno","c":"exp","af":"E1","ctx":"La hidrogenación del benceno a ciclohexano libera menos energía de la que se esperaría si el benceno tuviera tres dobles enlaces aislados, sin deslocalizar.","q":"¿Qué explica esta diferencia de energía?","o":["La deslocalización de los electrones π hace al benceno más estable de lo esperado, así que libera menos energía al hidrogenarse","El benceno no reacciona con H₂ y la energía medida en realidad corresponde a otra reacción del experimento","El ciclohexano formado es menos estable que el benceno y absorbe parte de la energía liberada","La hidrogenación del benceno es explosiva y parte de la energía se pierde como sonido y luz"]},{"t":"benceno","c":"uso","af":"I1","ctx":"En el siglo XIX, el cirujano Joseph Lister empezó a usar fenol (C₆H₅−OH) para desinfectar instrumentos y heridas, lo que redujo mucho las infecciones postoperatorias.","q":"¿En qué se diferencia estructuralmente el fenol del benceno?","o":["El fenol tiene un grupo −OH unido directamente al anillo aromático","El fenol no tiene ningún anillo aromático","El fenol tiene un átomo de nitrógeno dentro del anillo","El fenol tiene dos anillos aromáticos fusionados"]},{"t":"benceno","c":"exp","af":"E1","ctx":"La gasolina contiene una pequeña proporción de hidrocarburos aromáticos (benceno, tolueno, etilbenceno, xilenos) que mejoran el índice de octano, pero la normativa limita estrictamente el porcentaje de benceno permitido.","q":"¿Por qué se limita en particular el benceno y no tanto sus derivados metilados (tolueno, xilenos)?","o":["Porque el benceno es cancerígeno comprobado, mientras que sus derivados metilados son considerablemente menos tóxicos","Porque el benceno es el único de ellos que mejora el índice de octano de la gasolina","Porque el benceno es el único de ellos que es aromático y los demás son alcanos","Porque el benceno es más costoso de producir que el tolueno y los xilenos"]},{"t":"benceno","c":"uso","af":"I1","ctx":"Cuando un anillo de benceno está unido a una cadena de carbono más larga que él mismo, el anillo ya no se trata como la cadena principal: se nombra como sustituyente, con el nombre del grupo fenilo (C₆H₅−).","q":"¿Cómo se nombra un compuesto con un anillo de benceno unido a una cadena lineal de ocho carbonos?","o":["Como un octano con un sustituyente fenilo","Como un benceno con un sustituyente octilo","Con un nombre conservado, distinto de los dos anteriores","No se puede nombrar con las reglas de la IUPAC"]},{"t":"benceno","c":"uso","af":"I2","ctx":"El ácido salicílico, precursor de la aspirina, es un anillo de benceno con un grupo −COOH y, en el carbono vecino (orto), un grupo −OH.","q":"Como el −COOH tiene mayor prioridad que el −OH para dar el sufijo del nombre, ¿cuál es su nombre IUPAC?","o":["ácido 2-hidroxibenzoico","ácido 3-hidroxibenzoico","ácido 2-carboxifenólico","ácido O-hidroxibenzoico"]},{"t":"benceno","c":"uso","af":"I2","ctx":"El 2,4,6-triclorofenol se usó como conservante de la madera. Su anillo tiene un −OH y tres cloros: dos en las posiciones vecinas (orto) al −OH, y uno en la posición opuesta (para).","q":"¿Cuál es su nombre con los localizadores numéricos correctos (considerando el carbono del −OH como C1)?","o":["2,4,6-triclorofenol","2,3,6-triclorofenol","3,4,5-triclorofenol","2,4,5-triclorofenol"]},{"t":"benceno","c":"exp","af":"E1","ctx":"En la sustitución electrofílica aromática, cada sustituyente ya presente en el anillo \"dirige\" por dónde entra el siguiente grupo: unos dirigen a las posiciones orto y para, y otros a la posición meta.","q":"¿Qué tienen en común los grupos que dirigen a orto/para, como −CH₃ y −OH, frente a los que dirigen a meta, como −NO₂ y −COOH?","o":["Los directores orto/para aportan densidad electrónica al anillo (son activantes); los directores meta la retiran (son desactivantes)","Los directores orto/para siempre tienen átomos de oxígeno en su estructura; los directores meta nunca los tienen","Los directores orto/para son siempre gases a temperatura ambiente; los directores meta son siempre sólidos","No tienen nada en común: la posición a la que entra el nuevo grupo es aleatoria para cada sustituyente"]},{"t":"benceno","c":"ind","af":"N1","ctx":"El benceno, C₆H₆, se dibuja con tres dobles enlaces en la fórmula de Kekulé, pero no decolora el agua de bromo a temperatura ambiente, mientras que el ciclohexeno sí la decolora.","q":"¿Qué conclusión sacaron los químicos de esta evidencia?","o":["Los electrones del anillo de benceno están deslocalizados y el anillo es más estable que un alqueno común","El benceno no tiene átomos de carbono con dobles enlaces reales, así que no puede reaccionar con el bromo","El benceno es en realidad un alcano de cadena abierta, y no un anillo con dobles enlaces","El agua de bromo estaba dañada en el ensayo del benceno y por eso no se decoloró"]},{"t":"benceno","c":"ind","af":"N2","ctx":"Todos los enlaces carbono-carbono del benceno miden 0,139 nm. Un enlace C−C sencillo mide 0,154 nm y un enlace C=C mide 0,134 nm.","q":"¿Qué indican estos datos?","o":["Que los seis enlaces son iguales e intermedios entre sencillo y doble, lo que apoya el modelo de anillo con electrones deslocalizados","Que el benceno tiene tres enlaces sencillos y tres dobles que se alternan alrededor del anillo","Que el benceno solo tiene enlaces sencillos, porque su medida se acerca más a 0,154 nm","Que la longitud de los enlaces no tiene relación con la estructura de la molécula"]},{"t":"benceno","c":"ind","af":"N2","ctx":"Al nitrar tolueno se obtuvo una mezcla de productos: cerca de 59 % en posición orto, 37 % para y 4 % meta.","q":"¿Qué conclusión se apoya en los datos?","o":["El grupo metilo dirige la sustitución sobre todo a las posiciones orto y para","El grupo metilo dirige la sustitución sobre todo a la posición meta","El grupo metilo no influye: el nitro entra por igual en todas las posiciones","El producto meta es el principal porque está más lejos del metilo"]},{"t":"benceno","c":"ind","af":"N3","ctx":"Un grupo quiere saber si el tolueno es más volátil que el xileno. Tienen las dos sustancias, vidrios de reloj y un cronómetro, en una campana de extracción.","q":"¿Qué procedimiento es adecuado?","o":["Poner volúmenes iguales de cada líquido en vidrios iguales, a la misma temperatura, y medir cuánto tardan en evaporarse","Poner más tolueno que xileno en vidrios iguales y ver cuál de los dos desaparece primero","Calentar solo el xileno y comparar su tiempo de evaporación con el del tolueno sin calentar","Oler los dos líquidos al destaparlos y decidir cuál tiene el olor más fuerte y penetrante"]},{"t":"benceno","c":"ind","af":"N4","ctx":"Una estudiante predice que el benceno no reacciona con bromo sin catalizador. Mezcla benceno con bromo a temperatura ambiente y después de una hora el color naranja sigue igual.","q":"¿Los resultados apoyan su predicción?","o":["Sí: sin catalizador no se observó reacción en ese tiempo","No: el color se mantuvo porque el benceno disolvió todo el bromo","Sí, pero solo si el color hubiera desaparecido al instante","No: para saberlo habría que usar ciclohexeno en vez de benceno"]},{"t":"benceno","c":"ind","af":"N1","ctx":"Kekulé propuso en 1865 una estructura de anillo para el benceno; años después, la difracción de rayos X mostró que el anillo es plano y con todos los enlaces iguales.","q":"¿Qué muestra esta historia sobre los modelos científicos?","o":["Que un modelo útil se mejora cuando aparecen nuevas técnicas y evidencias","Que el primer modelo propuesto siempre es el definitivo y no cambia","Que los modelos se aceptan sin evidencia si su autor es reconocido","Que la difracción de rayos X demostró que el benceno no es un anillo"]},{"t":"benceno","c":"ind","af":"N4","ctx":"Un grupo comparó con qué rapidez reaccionan distintos compuestos aromáticos en una nitración. El benceno se tomó como referencia.","q":"¿Qué efecto tiene el grupo metilo sobre el anillo?","o":["Lo activa: el metilbenceno reacciona más rápido que el benceno","Lo desactiva: el metilbenceno reacciona más lento que el benceno","No tiene efecto: la rapidez es igual a la del benceno","Detiene la reacción por completo"],"tabla":[["Compuesto","Rapidez relativa"],["Benceno","1"],["Metilbenceno","25"],["Clorobenceno","0,03"],["Nitrobenceno","0,00000006"]],"exp":"El metilbenceno reacciona 25 veces más rápido que el benceno: el metilo cede electrones y activa el anillo. El cloro y el grupo nitro lo desactivan (0,03 y casi cero)."},{"t":"haluros","c":"exp","af":"E1","ctx":"Los CFC, como el CCl₂F₂, se usaron durante décadas en neveras y aerosoles. El Protocolo de Montreal acordó eliminarlos.","q":"¿Por qué se eliminaron?","o":["Porque la radiación UV los rompe en la estratosfera y libera cloro que destruye el ozono","Porque son muy inflamables y causaban incendios en las neveras","Porque se disuelven en la lluvia y forman ácido clorhídrico que acidifica los ríos","Porque al usarse en aerosoles producen monóxido de carbono"]},{"t":"haluros","c":"exp","af":"E1","ctx":"Al calentar bromoetano con una solución acuosa diluida de NaOH se obtiene etanol y bromuro de sodio.","q":"¿Cómo se clasifica esta reacción?","o":["Sustitución nucleofílica: el OH⁻ reemplaza al bromo, que sale como Br⁻","Adición electrofílica: el OH⁻ se suma a un doble enlace del etano","Eliminación: se forman eteno y agua al salir el bromo","Combustión: el bromoetano se oxida a CO₂ y agua"]},{"t":"haluros","c":"exp","af":"E1","ctx":"El 2-bromopropano se calienta con KOH disuelto en etanol (una base fuerte, sin agua).","q":"¿Cuál es el producto orgánico principal?","o":["propeno, por eliminación de HBr","propan-2-ol, por sustitución","propano, por reducción","2,2-dibromopropano, por adición"]},{"t":"haluros","c":"uso","af":"I1","ctx":"Los haluros de alquilo se clasifican según cuántos carbonos están unidos al carbono que lleva el halógeno.","q":"¿Cuál de los siguientes es un haluro de alquilo terciario?","o":["2-bromo-2-metilpropano","1-bromobutano","2-bromobutano","bromometano"]},{"t":"haluros","c":"ind","af":"N2","ctx":"Un grupo compara la rapidez con que reaccionan 1-clorobutano, 1-bromobutano y 1-yodobutano con el mismo nucleófilo, a la misma temperatura y concentración. Obtiene: yodo > bromo > cloro.","q":"¿Qué variable explica mejor la diferencia?","o":["La facilidad del halógeno para salir como ion: los halógenos más grandes son mejores grupos salientes","El número de carbonos de la cadena, que cambia en cada uno de los compuestos comparados","La electronegatividad: el halógeno más electronegativo es el que sale más rápido","La temperatura, que no pudo ser la misma en los tres ensayos del grupo"]},{"t":"haluros","c":"uso","af":"I1","ctx":"El 1-cloropropano y el 2-cloropropano son dos compuestos distintos, aunque los dos tienen la fórmula molecular C₃H₇Cl.","q":"¿En qué se diferencian estructuralmente?","o":["En la posición del cloro dentro de la cadena: en uno está en un carbono del extremo y en el otro, en el carbono del medio","En el número de átomos de carbono que tiene la cadena principal de cada compuesto","En el número de átomos de cloro que tiene cada una de las dos moléculas","En que uno es un alcano y el otro es un alqueno con un doble enlace en la cadena"]},{"t":"haluros","c":"exp","af":"E3","ctx":"El DDT, un insecticida muy usado hasta los años 70 y hoy prohibido en la mayoría de países, tiene varios enlaces C−Cl y es muy poco soluble en agua.","q":"¿Por qué el DDT persiste tanto tiempo en el ambiente y se acumula en los tejidos grasos de los animales?","o":["Porque sus enlaces C−Cl son poco reactivos y, al ser insoluble en agua, se acumula en las grasas","Porque el DDT reacciona rápidamente con el agua de lluvia y forma compuestos más estables","Porque el DDT se evapora poco después de aplicarse y vuelve al suelo con la lluvia","Porque el cloro del DDT es radiactivo y no lo descomponen las bacterias del suelo"]},{"t":"haluros","c":"exp","af":"E1","ctx":"El 2-bromo-2-metilpropano (terciario) reacciona con agua y forma el alcohol correspondiente mucho más rápido que el 1-bromobutano (primario), en las mismas condiciones.","q":"¿Qué explica esta diferencia de rapidez?","o":["El haluro terciario forma primero un carbocatión relativamente estable (mecanismo SN1); el primario no forma carbocationes estables con facilidad","El haluro primario tiene más átomos de carbono que el terciario, y una cadena más larga siempre reacciona más despacio","El bromo del haluro terciario es más electronegativo que el bromo del primario, así que sale del carbono con más facilidad","El haluro terciario tiene menos hidrógenos que el primario, y cada hidrógeno de menos acelera la reacción con el agua"]},{"t":"haluros","c":"uso","af":"I2","ctx":"El PVC (policloruro de vinilo), usado en tuberías, se fabrica polimerizando cloruro de vinilo, CH₂=CH−Cl.","q":"¿Cuál es el nombre IUPAC de este monómero?","o":["cloroeteno","cloroetano","1,1-dicloroeteno","cloroetino"]},{"t":"haluros","c":"exp","af":"E1","ctx":"El teflón, usado para recubrir sartenes antiadherentes, es politetrafluoroetileno, un polímero formado por unidades de tetrafluoroeteno (CF₂=CF₂).","q":"¿Por qué los enlaces C−F hacen que el teflón resista tanto el calor y evite reaccionar con otras sustancias?","o":["El enlace C−F es uno de los enlaces sencillos más fuertes y estables que puede formar el carbono","El flúor es poco electronegativo y por eso el enlace C−F es apolar","El enlace C−F se rompe con mucha facilidad y libera energía constantemente","El teflón es un compuesto iónico, sin enlaces covalentes"]},{"t":"haluros","c":"ind","af":"N2","ctx":"Para comparar la rapidez de distintos haluros de alquilo, un grupo agrega nitrato de plata (AgNO₃) en etanol a tubos con 2-cloro-2-metilpropano, 1-clorobutano y clorobenceno, y mide cuánto tardan en formar un precipitado blanco de AgCl.","q":"Si el mecanismo SN1 es más rápido en haluros terciarios, ¿qué resultado se espera?","o":["El tubo con 2-cloro-2-metilpropano forma el precipitado primero","El tubo con clorobenceno forma el precipitado primero","El tubo con 1-clorobutano forma el precipitado primero","Los tres tubos forman el precipitado al mismo tiempo"]},{"t":"haluros","c":"exp","af":"E1","ctx":"Los refrigerantes modernos (HFC, como el R-134a) reemplazaron a los CFC en neveras y aires acondicionados. Los HFC tienen flúor e hidrógeno, pero no cloro.","q":"¿Por qué eliminar el cloro de la molécula reduce el daño a la capa de ozono?","o":["Porque los enlaces C−F casi no se rompen con la radiación UV; es el cloro liberado de los C−Cl el que destruye el ozono en cadena","Porque sin cloro los HFC dejan de ser gases y ya no suben hasta la atmósfera, donde está la capa de ozono","Porque el flúor de los HFC reacciona con el oxígeno del aire y repara el ozono que ya se había destruido","Porque al quitar el cloro los HFC ya no contienen carbono y no pueden reaccionar con ninguna molécula"]},{"t":"haluros","c":"exp","af":"E1","ctx":"El enlace C−Cl es polar, pero el 1-clorobutano es prácticamente insoluble en agua, casi igual que el butano.","q":"¿Qué explica esta baja solubilidad?","o":["La mayor parte de la molécula es una cadena de carbono apolar, que domina sobre la polaridad del único enlace C−Cl","El cloro repele las moléculas de agua por tener una carga negativa permanente","El 1-clorobutano reacciona con el agua antes de poder disolverse en ella","Los haluros de alquilo siempre son solubles en agua; este sería un caso excepcional"]},{"t":"haluros","c":"uso","af":"I1","ctx":"Antes de los anestésicos modernos como el halotano, el cloroformo (triclorometano) se usó durante casi un siglo como anestésico inhalado, hasta que se comprobó que dañaba el hígado y el corazón.","q":"¿Cuál es la fórmula molecular del cloroformo?","o":["CHCl₃","CCl₄","CH₂Cl₂","CH₃Cl"]},{"t":"haluros","c":"uso","af":"I1","ctx":"Un haluro de alquilo se clasifica como primario, secundario o terciario según cuántos carbonos están unidos al carbono que lleva el halógeno.","q":"¿Cómo se clasifica el 2-bromobutano?","o":["Secundario, porque el carbono con el bromo está unido a otros dos carbonos","Primario, porque el carbono con el bromo está unido a un solo carbono","Terciario, porque el carbono con el bromo está unido a tres carbonos","No se puede clasificar sin ver la estructura completa"]},{"t":"haluros","c":"exp","af":"E1","ctx":"El 2-bromo-2-metilpropano (terciario) se calienta en etanol, sin una base fuerte añadida, y forma 2-metilpropeno junto con HBr.","q":"¿Cómo se llama el mecanismo de esta eliminación, dado que el haluro es terciario y no hay una base fuerte presente?","o":["E1: se forma primero un carbocatión terciario estable, y luego se pierde un H⁺ vecino","E2: el ataque de la base y la salida del halógeno ocurren en un solo paso","SN1: el nucleófilo ataca al carbocatión y sustituye al halógeno","SN2: el nucleófilo ataca por el lado opuesto al halógeno saliente"]},{"t":"haluros","c":"ind","af":"N2","ctx":"Un grupo hace reaccionar NaOH con tres haluros de alquilo distintos (1-clorobutano, 2-clorobutano y 2-cloro-2-metilpropano) en las mismas condiciones, y mide qué tan rápido ocurre la sustitución nucleofílica tipo SN2.","q":"¿Qué resultado se espera, si el mecanismo es SN2?","o":["El haluro primario (1-clorobutano) reacciona más rápido, porque el nucleófilo ataca con menos impedimento estérico","El haluro terciario reacciona más rápido, porque forma un carbocatión más estable","Los tres reaccionan a la misma velocidad, porque todos tienen un solo cloro","El haluro secundario siempre es el más rápido en cualquier mecanismo"]},{"t":"haluros","c":"ind","af":"N2","ctx":"Se comparan los puntos de ebullición de tres haluros de metilo: fluorometano (−78 °C), clorometano (−24 °C) y bromometano (4 °C).","q":"¿Qué tendencia muestran estos datos al aumentar el tamaño del halógeno?","o":["El punto de ebullición aumenta, porque los halógenos más grandes y pesados generan fuerzas de London más intensas","El punto de ebullición disminuye, porque los halógenos más grandes son menos electronegativos","El punto de ebullición no depende del halógeno, solo del número de carbonos","El punto de ebullición disminuye porque el enlace C−X se hace más polar"]},{"t":"haluros","c":"ind","af":"N2","ctx":"Se agregó nitrato de plata en etanol a tres haluros de la misma cadena y se midió el tiempo en que aparece un precipitado: 1-yodobutano, 1 minuto; 1-bromobutano, 5 minutos; 1-clorobutano, 30 minutos.","q":"¿Qué conclusión es coherente con los datos?","o":["La reactividad del enlace carbono-halógeno aumenta del cloro al yodo","El 1-clorobutano es el que reacciona más rápido","La longitud de la cadena causa las diferencias","Los tres haluros reaccionan con la misma rapidez"]},{"t":"haluros","c":"ind","af":"N3","ctx":"Un estudiante quiere saber si la temperatura acelera la reacción del 2-bromo-2-metilpropano con agua.","q":"¿Qué diseño experimental es adecuado?","o":["Hacer la misma reacción, con las mismas cantidades, a varias temperaturas, y medir en cada caso el tiempo de reacción","Usar varios haluros diferentes a la misma temperatura y medir cuál reacciona más rápido","Hacer una sola reacción en caliente y comparar su tiempo con lo que dice el libro","Cambiar al mismo tiempo la cantidad de agua y la temperatura en cada ensayo"]},{"t":"haluros","c":"ind","af":"N4","ctx":"Un estudiante predice que el 2-bromo-2-metilpropano forma precipitado con nitrato de plata en etanol más rápido que el 1-bromobutano. Observa: el primero, en segundos; el segundo, después de varios minutos.","q":"¿Los resultados apoyan su predicción?","o":["Sí: el haluro terciario reaccionó mucho más rápido, como predijo","No: los dos formaron precipitado, así que reaccionan igual de rápido","Sí, pero solo porque el 1-bromobutano tiene más carbonos en la cadena","No: el precipitado indica que no hubo reacción con ningún haluro"]},{"t":"haluros","c":"ind","af":"N2","ctx":"Puntos de ebullición: clorometano −24 °C, diclorometano 40 °C, triclorometano 61 °C, tetraclorometano 77 °C.","q":"¿Qué conclusión es coherente con los datos?","o":["Al aumentar los cloros aumenta la masa y las fuerzas entre moléculas, y sube el punto de ebullición","Al aumentar los cloros la molécula se vuelve iónica y por eso hierve más alto","El número de cloros no influye: las diferencias se deben a errores de medición","Al aumentar los cloros la molécula pierde carbono y se vuelve más volátil"]},{"t":"haluros","c":"ind","af":"N4","ctx":"Se compararon las velocidades relativas con que cuatro bromuros de alquilo reaccionan con un mismo nucleófilo en una sustitución de un solo paso.","q":"¿Qué tendencia muestran los datos?","o":["Cuanto más ramificado el carbono unido al bromo, más lenta la reacción","Cuanto más ramificado el carbono unido al bromo, más rápida la reacción","La rapidez no depende de la estructura del bromuro","La reacción es más rápida con el bromuro de menor masa molar"],"tabla":[["Bromuro","Rapidez relativa"],["Bromometano","1 000"],["Bromoetano","40"],["2-bromopropano","1"],["2-bromo-2-metilpropano","menor que 0,01"]],"exp":"La rapidez baja de 1 000 en el bromometano a menos de 0,01 en el bromuro más ramificado. Las ramas estorban el ataque del nucleófilo al carbono unido al bromo (impedimento espacial)."},{"t":"alcoholes","c":"exp","af":"E1","ctx":"En Colombia se han presentado intoxicaciones por licor adulterado con metanol, que se parece mucho al etanol.","q":"¿Por qué el metanol es tan peligroso?","o":["El cuerpo lo oxida a metanal y ácido metanoico, que son tóxicos y pueden causar ceguera","El metanol es una base fuerte que quema el estómago","El metanol no se absorbe y se acumula en los pulmones","El metanol se acumula en la sangre sin transformarse y la vuelve ácida de inmediato"]},{"t":"alcoholes","c":"uso","af":"I1","ctx":"En Colombia la gasolina se mezcla con etanol obtenido de la caña de azúcar.","q":"¿Cuál es la ecuación balanceada de la combustión completa del etanol?","o":["C₂H₅OH + 3 O₂ → 2 CO₂ + 3 H₂O","C₂H₅OH + 2 O₂ → 2 CO₂ + 3 H₂O","C₂H₅OH + 3 O₂ → 2 CO + 3 H₂O","C₂H₅OH + O₂ → CH₃COOH + H₂O"]},{"t":"fenoles","c":"uso","af":"I1","ctx":"Alcoholes y fenoles tienen el grupo −OH, pero unido a átomos de carbono diferentes.","q":"¿Cuál de las siguientes sustancias es un fenol y no un alcohol?","o":["C₆H₅−OH, porque el −OH está unido directamente al anillo aromático","C₆H₅−CH₂−OH, porque tiene un anillo aromático","C₆H₁₁−OH (ciclohexanol), porque el −OH está en un anillo","CH₃−OH, porque es el alcohol más simple"]},{"t":"alcoholes","c":"ind","af":"N2","ctx":"Un grupo agrega dicromato de potasio acidificado (color naranja) a tres tubos con butan-1-ol, butan-2-ol y 2-metilpropan-2-ol. Solo en dos tubos la solución se vuelve verde.","q":"¿En qué tubo NO hay cambio y por qué?","o":["En el de 2-metilpropan-2-ol, porque es un alcohol terciario y su carbono con −OH no tiene hidrógenos","En el de butan-1-ol, porque los alcoholes primarios no tienen hidrógenos en el carbono del −OH","En el de butan-2-ol, porque los alcoholes secundarios solo se oxidan con luz ultravioleta","En ninguno: los tres deberían cambiar de color porque todos tienen un grupo −OH"]},{"t":"alcoholes","c":"uso","af":"I1","ctx":"El anticongelante de los radiadores contiene etano-1,2-diol (etilenglicol), un alcohol con dos grupos −OH.","q":"¿Cuál es su fórmula estructural?","o":["HO−CH₂−CH₂−OH","HO−CH₂−CH₃","CH₃−CH(OH)−CH₃","HO−CH₂−CH(OH)−CH₂−OH"]},{"t":"eteres","c":"uso","af":"I1","ctx":"La glicerina (propano-1,2,3-triol), que forma parte de las grasas (combinada en los triglicéridos), se usa en cosméticos, jarabes y jabones por su capacidad de retener agua.","q":"¿Cuántos grupos −OH tiene la glicerina?","o":["Tres","Uno","Dos","Ninguno: es un éter"]},{"t":"alcoholes","c":"uso","af":"I1","ctx":"Una botella de aguardiente antioqueño indica «29 °GL», es decir, 29 % de etanol en volumen; una cerveza típica tiene entre 4 °GL y 5 °GL.","q":"¿Qué significa, en términos químicos, que una bebida tenga un grado GL más alto?","o":["Que un mayor porcentaje del volumen de la bebida es etanol puro","Que la bebida tiene más azúcar sin fermentar","Que la bebida tiene más agua que etanol","Que la bebida se fermentó a una temperatura mayor"]},{"t":"alcoholes","c":"exp","af":"E1","ctx":"El metanol, el etanol y el propan-1-ol se mezclan con agua en cualquier proporción, pero el octan-1-ol forma dos capas separadas al mezclarse con agua.","q":"¿Qué explica que el octan-1-ol sea mucho menos soluble en agua que los alcoholes más pequeños?","o":["Su cadena de carbono, larga y apolar, pesa más en la molécula que el único grupo −OH polar","El octan-1-ol no tiene grupo −OH, así que no puede interactuar con el agua","El octan-1-ol es un ácido y no un alcohol, por eso no se mezcla con el agua","El agua reacciona con el octan-1-ol y forma un gas que separa las dos capas"]},{"t":"alcoholes","c":"exp","af":"E1","ctx":"El gel antibacterial para manos contiene alcohol (etanol o isopropanol) en alta concentración, que se evapora con rapidez después de aplicarlo.","q":"¿Qué propiedad del alcohol explica esa evaporación rápida, comparada con el agua pura?","o":["Sus moléculas se atraen entre sí con menos fuerza que las del agua, por lo que escapan al aire con más facilidad","El alcohol hierve a una temperatura mucho mayor que el agua, por eso se calienta antes","El alcohol no forma puentes de hidrógeno, porque no tiene átomos de oxígeno","El agua se evapora siempre más rápido que cualquier alcohol a la misma temperatura"]},{"t":"alcoholes","c":"exp","af":"E1","ctx":"En Colombia la gasolina se mezcla con etanol como oxigenante, lo que ayuda a una combustión más completa y reduce las emisiones de monóxido de carbono.","q":"¿Por qué agregar un compuesto con oxígeno al combustible ayuda a reducir el CO emitido?","o":["Porque aporta oxígeno a la combustión y el carbono se oxida hasta CO₂ en vez de quedar como CO","Porque el etanol enfría el motor y eso evita que se forme CO","Porque el etanol no se quema y simplemente diluye los gases de escape","Porque el etanol reacciona con el CO después de la combustión y lo elimina"]},{"t":"eteres","c":"exp","af":"E1","ctx":"El propano (M=44 g/mol), el metoxietano (un éter, M=60 g/mol) y el propan-1-ol (M=60 g/mol) hierven a −42 °C, 7 °C y 97 °C, respectivamente.","q":"¿Qué explica que el propan-1-ol hierva a una temperatura mucho mayor que el éter, de masa molar parecida?","o":["El propan-1-ol forma puentes de hidrógeno entre sus moléculas gracias al −OH; el éter no puede formarlos entre las suyas","El propan-1-ol tiene mayor masa molar que el éter, y a más masa molar el punto de ebullición sube mucho","El éter tiene un enlace C−O−C más fuerte que el enlace C−OH del alcohol, así que sus moléculas se separan fácil","El éter forma puentes de hidrógeno entre sus moléculas, pero son más débiles que los del alcohol"]},{"t":"alcoholes","c":"exp","af":"E1","ctx":"Un alcohol primario con CrO₃/H⁺ (oxidante fuerte) sigue hasta ácido carboxílico; con clorocromato de piridinio, CCP (oxidante suave), se detiene en el aldehído. Un alcohol secundario, en cambio, da el mismo producto con cualquiera de los dos oxidantes.","q":"¿Por qué un alcohol secundario no se ve afectado por la fuerza del oxidante, a diferencia del primario?","o":["Porque la cetona que se forma no tiene un hidrógeno en el carbonilo, así que no puede oxidarse más","Porque los alcoholes secundarios no reaccionan con ningún oxidante","Porque el CCP no reacciona nunca con alcoholes secundarios","Porque los alcoholes secundarios siempre dan ácido carboxílico, sin importar el oxidante"]},{"t":"eteres","c":"exp","af":"E1","ctx":"El etanol reacciona con H₂SO₄ concentrado como catalizador, pero el producto depende de la temperatura: a unos 140 °C se favorece la deshidratación intermolecular (entre dos moléculas de alcohol) y a unos 180 °C, la intramolecular (dentro de una sola molécula).","q":"¿Qué producto se espera a 140 °C?","o":["Un éter (etoxietano), por la unión de dos moléculas de etanol con pérdida de agua","Un alqueno (eteno), por eliminación dentro de una sola molécula","Un ácido carboxílico, por oxidación del alcohol","Ningún cambio: el H₂SO₄ no reacciona a esa temperatura"]},{"t":"fenoles","c":"exp","af":"E1","ctx":"El fenol (C₆H₅−OH) reacciona con NaOH y forma una sal (fenóxido de sodio) soluble en agua; el etanol, en cambio, no reacciona con NaOH.","q":"¿Qué explica esta diferencia?","o":["El fenol es un ácido débil (su −OH cede H⁺ con más facilidad, porque el anillo aromático estabiliza la carga negativa que queda); el etanol no es ácido en esas condiciones","El fenol tiene un átomo de oxígeno extra que el etanol no tiene, y ese oxígeno es el que reacciona con el NaOH para formar la sal","El etanol es una base y por eso no puede reaccionar con otra base como el NaOH, mientras que el fenol es neutro","El fenol no tiene ningún grupo −OH: reacciona con el NaOH porque el anillo aromático cede un hidrógeno"]},{"t":"eteres","c":"exp","af":"E1","ctx":"Para preparar un éter a partir de un alcóxido de sodio (R−O⁻Na⁺) y un haluro de alquilo (R′−X), como en la síntesis de Williamson, el ion alcóxido actúa como nucleófilo y ataca al carbono unido al halógeno.","q":"¿Qué tipo de reacción es esta síntesis?","o":["Sustitución nucleofílica: el alcóxido reemplaza al halógeno","Adición electrofílica sobre un doble enlace","Eliminación, formando un alqueno","Oxidación del alcóxido a un ácido carboxílico"]},{"t":"eteres","c":"exp","af":"E1","ctx":"El etoxietano (dietil éter) hierve a 35 °C, mucho más bajo que el butan-1-ol (118 °C), aunque los dos tienen una masa molar parecida (74 g/mol).","q":"¿Qué explica esta diferencia tan grande en el punto de ebullición?","o":["El éter no tiene ningún H unido a O, así que sus moléculas no pueden formar puentes de hidrógeno entre sí; el alcohol sí","El éter tiene una masa molar mucho menor que el alcohol y por eso necesita menos energía para hervir","El alcohol es un compuesto iónico y el éter es covalente, así que sus moléculas se atraen menos","El éter reacciona con el aire antes de hervir y lo que se mide es la temperatura de otra sustancia"]},{"t":"alcoholes","c":"ind","af":"N4","ctx":"Solubilidad en agua a 20 °C: el metanol, el etanol y el propan-1-ol se mezclan con agua en cualquier proporción; del butan-1-ol se disuelven 7,7 g en 100 mL; del pentan-1-ol, 2,2 g; del hexan-1-ol, 0,6 g.","q":"¿Qué patrón muestran los datos?","o":["A medida que la cadena de carbono es más larga, el alcohol es menos soluble en agua","Los alcoholes de cadena larga son los más solubles","La solubilidad no depende de la longitud de la cadena","Todos los alcoholes se mezclan con el agua en cualquier proporción"]},{"t":"alcoholes","c":"ind","af":"N3","ctx":"Una estudiante tiene dos frascos sin rótulo: uno con propan-1-ol (alcohol primario) y otro con 2-metilpropan-2-ol (alcohol terciario). Tiene dicromato de potasio acidificado, de color naranja, que se vuelve verde cuando oxida a un alcohol.","q":"¿Qué resultado le permite identificar los frascos?","o":["El frasco que pasa de naranja a verde es el alcohol primario; el terciario no se oxida y queda naranja","Los dos frascos se vuelven verdes, porque ambos alcoholes tienen un grupo −OH que se oxida","El alcohol terciario se vuelve verde y el primario queda naranja, porque tiene más carbonos","Ninguno cambia de color, porque el dicromato solo reacciona con aldehídos y cetonas"]},{"t":"alcoholes","c":"ind","af":"N3","ctx":"Una estudiante quiere comparar qué tan rápido se evaporan el etanol y el agua. Tiene goteros, papel filtro y un cronómetro.","q":"¿Qué procedimiento es adecuado?","o":["Poner una gota del mismo tamaño de cada líquido en papeles iguales, al mismo tiempo, y medir cuánto tarda en secarse cada una","Poner una gota de etanol al sol y una de agua a la sombra, y medir cuánto tarda en secarse cada una","Poner varias gotas de agua y una sola de etanol, y medir cuál de las dos manchas desaparece antes","Oler las dos gotas cada minuto y decidir por el olor cuál de los dos líquidos se evaporó primero"]},{"t":"alcoholes","c":"ind","af":"N2","ctx":"Se agregó un trozo pequeño de sodio a tres tubos: con etanol se formaron burbujas despacio; con agua, rápido; con hexano, nada.","q":"¿Qué conclusión se apoya en las observaciones?","o":["El etanol y el agua tienen un hidrógeno unido a oxígeno que reacciona con el sodio","El hexano reacciona con el sodio, pero sin formar burbujas visibles","El etanol reacciona más rápido que el agua porque tiene más carbonos","El sodio reacciona igual con todas las sustancias líquidas"]},{"t":"alcoholes","c":"ind","af":"N4","ctx":"Un estudiante predice que el butan-2-ol, al oxidarse con dicromato, forma una cetona. El producto da positiva la prueba de 2,4-dinitrofenilhidrazina y negativa la de Tollens.","q":"¿Los resultados apoyan su predicción?","o":["Sí: hay un carbonilo y no es aldehído, así que es una cetona","No: la prueba positiva de 2,4-dinitrofenilhidrazina indica un alcohol","Sí, pero solo si la prueba de Tollens también hubiera sido positiva","No: el dicromato no oxida alcoholes secundarios"]},{"t":"alcoholes","c":"ind","af":"N2","ctx":"Solubilidad de tres alcoholes de cuatro carbonos en 100 mL de agua: butan-1-ol 7,7 g; butan-2-ol 18 g; 2-metilpropan-2-ol, se mezcla en cualquier proporción.","q":"¿Qué conclusión es coherente con los datos?","o":["Con el mismo número de carbonos, la forma más compacta se disuelve mejor en agua","Los tres son igual de solubles, porque tienen el mismo número de carbonos","El butan-1-ol es el más soluble porque su cadena es la más larga","La solubilidad no depende de la estructura, solo de la masa molar"]},{"t":"alcoholes","c":"ind","af":"N1","ctx":"La ley colombiana fija un límite de metanol en las bebidas alcohólicas, después de que análisis de laboratorio encontraran metanol en licores adulterados.","q":"¿Por qué esa norma se apoya en el conocimiento científico?","o":["Porque se basa en análisis químicos que identifican y miden una sustancia tóxica","Porque se basa en la opinión de los consumidores sobre el sabor del licor","Porque el metanol y el etanol son la misma sustancia con distinto nombre","Porque cualquier alcohol en una bebida es tóxico en la misma medida"]},{"t":"alcoholes","c":"ind","af":"N4","ctx":"Un grupo midió cuánto se disuelve de cada alcohol de cadena lineal en 100 mL de agua a 20 °C.","q":"¿Cómo se explica la disminución de la solubilidad?","o":["La parte apolar crece y pesa más que el grupo OH, que forma puentes de hidrógeno","El grupo OH desaparece de la molécula cuando la cadena crece más","Los alcoholes grandes son menos polares porque tienen menos oxígeno que los pequeños","Los alcoholes grandes reaccionan con el agua y se descomponen al mezclarse"],"tabla":[["Alcohol","Carbonos","Solubilidad (g/100 mL)"],["Metanol","1","Total"],["1-propanol","3","Total"],["1-butanol","4","7,4"],["1-pentanol","5","2,2"],["1-hexanol","6","0,6"]],"exp":"Hasta 3 carbonos los alcoholes se disuelven totalmente; desde 4 la solubilidad baja (7,4; 2,2; 0,6 g). El grupo OH forma puentes de hidrógeno con el agua, pero la cadena apolar crece y termina dominando. El OH sigue estando en la molécula."},{"t":"aldehidos","c":"exp","af":"E1","ctx":"En el nombre 3-metilbutanal se indica la posición del metilo, pero no la del grupo −CHO.","q":"¿Por qué no se escribe el localizador del −CHO?","o":["Porque en una cadena abierta el carbono del −CHO siempre es el C1","Porque los aldehídos nunca llevan localizadores","Porque el −CHO se nombra como sustituyente y no como sufijo","Porque el metilo tiene prioridad sobre el aldehído"]},{"t":"cetonas","c":"exp","af":"E1","ctx":"El formol, que se usa para conservar muestras biológicas, es una solución acuosa de metanal.","q":"¿Por qué se recomienda manipularlo con ventilación, guantes y gafas?","o":["Porque el metanal es tóxico e irritante y está clasificado como cancerígeno","Porque el metanal es muy inflamable incluso disuelto en agua","Porque el formol es un ácido fuerte que corroe la piel","Porque el metanal es inodoro y no se nota si hay fugas"]},{"t":"aldehidos","c":"ind","af":"N2","ctx":"Para distinguir propanal de propanona, se calienta suavemente cada uno con reactivo de Tollens (nitrato de plata amoniacal).","q":"¿Qué observación identifica al aldehído?","o":["Se forma un espejo de plata en el tubo del propanal","Se forma un espejo de plata en el tubo de la propanona","Ambos tubos forman un precipitado rojo ladrillo","Ninguno cambia, porque los dos tienen grupo carbonilo"]},{"t":"aldehidos","c":"exp","af":"E1","ctx":"Los aldehídos se oxidan con facilidad a ácidos carboxílicos, mientras que las cetonas resisten la oxidación en condiciones suaves.","q":"¿Qué explica esta diferencia?","o":["El carbono del carbonilo del aldehído tiene un hidrógeno unido; el de la cetona está unido a dos carbonos","Las cetonas no tienen grupo carbonilo, por eso resisten la oxidación en condiciones suaves","Los aldehídos tienen un triple enlace C≡O, que es más fácil de romper que el doble","Las cetonas son siempre gases y no alcanzan a reaccionar dentro de una solución acuosa"]},{"t":"aldehidos","c":"uso","af":"I1","ctx":"En personas con diabetes no controlada el aliento puede oler a «quitaesmalte». Ese olor se debe a la propanona que se produce cuando el cuerpo degrada grasas.","q":"¿A qué grupo funcional pertenece la propanona?","o":["Cetona","Aldehído","Éster","Alcohol"]},{"t":"aldehidos","c":"uso","af":"I1","ctx":"La vainillina, responsable del aroma y sabor de la vainilla, es un aldehído aromático que también se usa en perfumería y repostería.","q":"¿Qué grupo funcional identifica a la vainillina como aldehído?","o":["−CHO","−COOH","−O−CH₃","−OH"]},{"t":"aldehidos","c":"ind","af":"N2","ctx":"Antes de los glucómetros electrónicos se usaba el reactivo de Fehling (sulfato de cobre en medio básico, de color azul) para detectar azúcares reductores, como la glucosa, en la orina de personas con sospecha de diabetes.","q":"¿Qué cambio se observa cuando el reactivo de Fehling reacciona con un aldehído como el de la glucosa?","o":["Se forma un precipitado rojo ladrillo de óxido de cobre(I), porque el aldehído se oxida y reduce al cobre","La solución se vuelve completamente transparente porque el cobre se evapora","Se forma un gas que hace burbujear la mezcla y luego desaparece el color","El color azul se intensifica sin que se forme ningún precipitado en el tubo"]},{"t":"aldehidos","c":"uso","af":"I1","ctx":"El aldehído cinámico (C₆H₅−CH=CH−CHO) es el responsable del aroma y el sabor característico de la canela.","q":"¿Qué grupos funcionales tiene esta molécula, además del anillo aromático?","o":["Un doble enlace C=C y un grupo aldehído (−CHO)","Dos grupos −OH en la cadena","Un grupo éster y un grupo amida","Un triple enlace y una cetona"]},{"t":"aldehidos","c":"uso","af":"I1","ctx":"El metanal (formaldehído) es un gas que se usa para fabricar las resinas que unen las partículas de madera en los muebles de aglomerado.","q":"¿Cuál es la fórmula estructural del metanal?","o":["H−CHO","CH₃−CHO","H−COOH","CH₃−OH"]},{"t":"cetonas","c":"ind","af":"N2","ctx":"Un grupo agrega dicromato de potasio acidificado (color naranja) a dos tubos, en las mismas condiciones: uno con ciclohexanol y otro con ciclohexanona.","q":"¿Qué resultado se espera?","o":["Solo cambia a verde el tubo con ciclohexanol","Solo el tubo con ciclohexanona cambia de color","Los dos tubos cambian de color por igual","Ninguno de los dos tubos cambia de color"]},{"t":"cetonas","c":"exp","af":"E1","ctx":"La acetona (propanona) del quitaesmalte disuelve tanto el esmalte de uñas (orgánico, apolar) como manchas de sustancias polares, y además se mezcla con agua en cualquier proporción.","q":"¿Qué característica de la acetona explica que disuelva sustancias tan distintas entre sí?","o":["Tiene una parte polar (C=O) y una parte apolar (dos grupos metilo)","La acetona es un compuesto iónico que se disuelve en cualquier líquido","La acetona no tiene ningún átomo de oxígeno en su estructura","La acetona reacciona químicamente con todo lo que disuelve"]},{"t":"aldehidos","c":"exp","af":"E1","ctx":"A masa molar parecida, los alcanos tienen el punto de ebullición más bajo, los aldehídos y las cetonas uno intermedio, y los alcoholes el más alto.","q":"¿Qué explica que los aldehídos y las cetonas hiervan a mayor temperatura que los alcanos, pero a menor temperatura que los alcoholes?","o":["El grupo C=O es polar y permite atracciones dipolo-dipolo entre moléculas, pero no puentes de hidrógeno entre ellas mismas, al no tener un H unido al O","Los aldehídos y las cetonas no tienen ningún tipo de fuerza entre sus moléculas, y hierven más alto solo porque son más pesados","Los aldehídos y las cetonas forman puentes de hidrógeno entre sus moléculas, más fuertes incluso que los de los alcoholes","El grupo C=O hace que la molécula pese menos que un alcano del mismo tamaño, y eso sube su punto de ebullición"]},{"t":"cetonas","c":"uso","af":"I1","ctx":"La etil metil cetona (butan-2-ona, MEK) es un disolvente industrial común en pinturas, pegantes y barnices.","q":"¿Cuál es su fórmula estructural?","o":["CH₃−CO−CH₂−CH₃","CH₃−CH₂−CO−CH₂−CH₃","CH₃−CH₂−CH₂−CHO","CH₃−CH(OH)−CH₂−CH₃"]},{"t":"aldehidos","c":"uso","af":"I1","ctx":"En la retina del ojo humano, el retinal (un aldehído derivado de la vitamina A) cambia de forma geométrica al absorber luz, lo que dispara la señal nerviosa de la visión.","q":"¿Qué tienen en común el retinal y otros aldehídos, sin importar su tamaño?","o":["Todos tienen un grupo −CHO: un carbonilo (C=O) unido al menos a un hidrógeno","Todos tienen un anillo aromático unido al carbonilo","Todos son solubles en agua en cualquier proporción","Todos tienen el mismo número de átomos de carbono"]},{"t":"aldehidos","c":"uso","af":"I2","ctx":"El cinamaldehído, responsable del aroma y sabor de la canela, también se usa como repelente de insectos. Su estructura es C₆H₅−CH=CH−CHO.","q":"¿Cuál es su nombre IUPAC?","o":["3-fenilprop-2-enal","3-fenilbut-2-enal","benceno-2-enocarbaldehído","prop-2-enobencenocarbaldehído"]},{"t":"aldehidos","c":"exp","af":"E1","ctx":"Los aldehídos dan positivas las pruebas de Tollens y Fehling (se oxidan con facilidad); las cetonas no reaccionan con ninguno de los dos reactivos.","q":"¿Qué explica que las cetonas no se oxiden en estas pruebas?","o":["El carbono del carbonilo de una cetona está unido a dos carbonos, sin ningún H que perder en la oxidación","Las cetonas no tienen ningún átomo de oxígeno en su estructura","Las cetonas son siempre gases y no pueden reaccionar en un tubo de ensayo","Las cetonas reaccionan igual que los aldehídos, pero más lento"]},{"t":"aldehidos","c":"exp","af":"E1","ctx":"El NaBH₄ reduce el grupo carbonilo (C=O) de un aldehído o una cetona a un alcohol, pero no reduce un doble enlace C=C presente en la misma molécula.","q":"¿Cómo se llama esta capacidad de un reactivo para transformar un grupo funcional sin afectar a otro presente en la misma molécula?","o":["Quimioselectividad","Isomería","Hibridación","Deslocalización electrónica"]},{"t":"aldehidos","c":"ind","af":"N2","ctx":"Se aplicó el reactivo de Tollens a tres muestras: el propanal forma un espejo de plata, la propanona no cambia y una muestra desconocida X forma un espejo de plata.","q":"¿Qué se puede concluir de la muestra X?","o":["Que probablemente contiene un grupo aldehído","Que es una cetona","Que es un alcano","Que no se puede concluir nada porque no se comparó con otras muestras"]},{"t":"cetonas","c":"ind","af":"N2","ctx":"Puntos de ebullición de tres compuestos de masa molar parecida: butano (58 g/mol), −1 °C; propanal (58 g/mol), 49 °C; propan-1-ol (60 g/mol), 97 °C.","q":"¿Qué explicación es coherente con los datos?","o":["El grupo C=O polar del propanal sube su punto de ebullición respecto al butano, pero queda por debajo del alcohol, que forma puentes de hidrógeno entre sus moléculas","La diferencia de masa molar explica toda la diferencia: el propan-1-ol pesa 2 g/mol más y por eso hierve casi 50 °C más","El butano forma puentes de hidrógeno entre sus moléculas, pero se rompen con facilidad, por eso hierve tan bajo","El propanal forma más puentes de hidrógeno que el alcohol, aunque hierve más bajo porque su molécula es más pequeña"]},{"t":"aldehidos","c":"ind","af":"N3","ctx":"Un grupo debe identificar tres frascos: propanal, propanona y propan-1-ol. Tiene reactivo de Tollens y 2,4-dinitrofenilhidrazina.","q":"¿Qué procedimiento les permite identificarlos?","o":["Usar la 2,4-dinitrofenilhidrazina para hallar los carbonilos y luego Tollens para separar el aldehído","Usar solo Tollens, porque reacciona distinto con los tres compuestos","Oler los tres frascos y decidir por el olor cuál es cada compuesto","Calentar los tres frascos y ver cuál hierve primero sin usar reactivos"]},{"t":"cetonas","c":"ind","af":"N2","ctx":"Solubilidad en agua a 20 °C: propanona, en cualquier proporción; butanona, 27 g/100 mL; pentan-3-ona, 5 g/100 mL.","q":"¿Qué conclusión es coherente con los datos?","o":["A medida que crece la cadena de la cetona, disminuye su solubilidad en agua","A medida que crece la cadena de la cetona, aumenta su solubilidad en agua","La solubilidad de las cetonas no depende de la longitud de la cadena","Las cetonas no son solubles en agua porque no tienen oxígeno"]},{"t":"aldehidos","c":"ind","af":"N4","ctx":"Una estudiante predice que la fructosa no da positiva la prueba de Fehling porque es una cetosa. En el ensayo, la fructosa formó el precipitado rojo ladrillo.","q":"¿Qué se puede decir de su predicción?","o":["Los datos la refutan: la fructosa sí redujo el reactivo en ese ensayo","Los datos la apoyan: el precipitado rojo indica que no hubo reacción","No se puede evaluar, porque la fructosa no es un carbohidrato","Los datos la apoyan si el precipitado hubiera sido azul en vez de rojo"]},{"t":"aldehidos","c":"ind","af":"N2","ctx":"Una estudiante probó tres compuestos carbonílicos con el reactivo de Tollens y con el de Fehling.","q":"¿Qué se puede concluir?","o":["La muestra 1 es un aldehído; las muestras 2 y 3 no lo son","Las tres son aldehídos porque tienen grupo carbonilo","La muestra 1 es una cetona porque forma precipitado","No se concluye nada porque las dos pruebas dan lo mismo en todas"],"tabla":[["Muestra","Reactivo de Tollens","Reactivo de Fehling"],["1","Espejo de plata","Precipitado rojo"],["2","Sin cambio","Sin cambio"],["3","Sin cambio","Sin cambio"]],"exp":"Solo la muestra 1 forma espejo de plata y precipitado rojo, que son las pruebas de los aldehídos. Las cetonas también tienen carbonilo pero no reaccionan, así que tener carbonilo no basta para ser aldehído."},{"t":"esteres","c":"uso","af":"I1","ctx":"El aroma del banano se debe en parte al etanoato de 3-metilbutilo, un éster que la industria también produce para dar sabor a dulces.","q":"¿De qué par de reactivos se obtiene este éster por esterificación?","o":["ácido etanoico y 3-metilbutan-1-ol","ácido 3-metilbutanoico y etanol","etanal y 3-metilbutanal","ácido etanoico y 3-metilbutanal"]},{"t":"acidos","c":"exp","af":"E1","ctx":"El vinagre contiene ácido etanoico. Una solución de vinagre tiene pH cercano a 3, mientras que una de HCl de la misma concentración tiene pH mucho menor.","q":"¿Qué explica estas observaciones?","o":["El −COOH cede solo parcialmente su H⁺ al agua: el ácido etanoico es un ácido débil","El −COOH libera iones OH⁻ al agua y por eso el pH sube a 3","El ácido etanoico se ioniza por completo, igual que el HCl","El ácido etanoico no tiene hidrógenos que pueda ceder al agua"]},{"t":"esteres","c":"ind","af":"N3","ctx":"En una práctica se calienta aceite de palma con NaOH y se espera obtener jabón y glicerol.","q":"¿Qué evidencia es más adecuada para comprobar que se formó jabón?","o":["El producto forma espuma al agitarlo con agua y ayuda a retirar una mancha de grasa","El aceite cambia de color al calentarse con el NaOH en el recipiente","El volumen de la mezcla aumenta cuando se calienta en la estufa","Se desprende un gas que enturbia el agua de cal en otro tubo"]},{"t":"esteres","c":"uso","af":"I1","ctx":"Colombia mezcla el diésel con biodiésel elaborado a partir de aceite de palma. El biodiésel está formado principalmente por ésteres metílicos de ácidos grasos.","q":"¿Qué reacción lo produce?","o":["Transesterificación del aceite (un triglicérido) con metanol","Hidrogenación del aceite con H₂ y níquel","Fermentación de la glucosa de la palma","Combustión incompleta del aceite de palma"]},{"t":"acidos","c":"exp","af":"E1","ctx":"El ácido etanoico (60 g/mol) hierve a 118 °C y el propan-1-ol (60 g/mol) a 97 °C.","q":"¿Por qué el ácido hierve a mayor temperatura si tienen la misma masa molar?","o":["Las moléculas del ácido se asocian en parejas (dímeros) unidas por dos puentes de hidrógeno, y separarlas exige más energía","El ácido etanoico tiene una masa molar mucho mayor que el propan-1-ol, y eso basta para explicar la diferencia","El propan-1-ol no puede formar puentes de hidrógeno porque su −OH está unido a un carbono apolar","El ácido etanoico es un compuesto iónico, formado por iones H⁺ y acetato, que se atraen con fuerza"]},{"t":"acidos","c":"uso","af":"I1","ctx":"La picadura de hormiga y el pelo urticante de la ortiga liberan ácido metanoico (ácido fórmico), el ácido carboxílico más simple.","q":"¿Cuál es su fórmula estructural?","o":["H−COOH","CH₃−COOH","H−CHO","CH₃−CH₂−COOH"]},{"t":"acidos","c":"uso","af":"I1","ctx":"Una botella de vinagre comercial indica «acidez: 4 % m/v», es decir, hay 4 gramos de ácido etanoico por cada 100 mL de vinagre.","q":"¿Qué significa, en términos químicos, un vinagre con mayor porcentaje de acidez?","o":["Contiene una mayor concentración de ácido etanoico disuelto en agua","Contiene menos agua y más azúcar","Es menos ácido que uno con menor porcentaje","Contiene ácido clorhídrico en vez de ácido etanoico"]},{"t":"esteres","c":"exp","af":"E1","ctx":"El nailon, una fibra sintética usada en textiles y cuerdas, se forma al unir repetidamente moléculas con grupo ácido carboxílico con moléculas con grupo amina, liberando agua en cada unión.","q":"¿Qué grupo funcional se forma en cada punto de unión de la cadena del nailon?","o":["Amida (−CO−NH−)","Éster (−CO−O−)","Éter (−O−)","Nitrilo (−C≡N)"]},{"t":"acidos","c":"uso","af":"I1","ctx":"El olor característico de la mantequilla rancia se debe en parte al ácido butanoico, que se libera cuando las grasas se descomponen.","q":"¿Cuál es su fórmula estructural?","o":["CH₃−CH₂−CH₂−COOH","CH₃−CH₂−COOH","CH₃−CH₂−CH₂−CH₂−COOH","CH₃−CH₂−CH₂−CHO"]},{"t":"esteres","c":"uso","af":"I1","ctx":"La aspirina se sintetiza haciendo reaccionar ácido salicílico (que tiene un grupo −OH en el anillo) con anhídrido acético, para formar un grupo éster.","q":"¿Qué dos partes de las moléculas quedan unidas por el nuevo enlace éster?","o":["El oxígeno del −OH del ácido salicílico y el carbono carbonilo que aporta el anhídrido acético","Dos anillos aromáticos, uno de cada reactivo, unidos entre sí","El nitrógeno de un grupo amina y el carbono de un grupo ácido","Los carbonos de dos grupos −COOH que pierden una molécula de agua"]},{"t":"acidos","c":"ind","af":"N2","ctx":"Una sustancia orgánica desconocida puede ser un alcohol o un ácido carboxílico. Para saberlo, un grupo le agrega bicarbonato de sodio (NaHCO₃) sólido.","q":"¿Qué observación indicaría que es el ácido carboxílico?","o":["Se forman burbujas de CO₂ de inmediato, porque el ácido reacciona con el bicarbonato","La mezcla cambia a color azul porque el ácido tiñe el bicarbonato","No ocurre ningún cambio visible porque los ácidos orgánicos son débiles","Se forma un precipitado blanco sin liberar gas, porque el bicarbonato no se disuelve"]},{"t":"acidos","c":"uso","af":"I2","ctx":"El benzoato de sodio, sal de sodio del ácido C₆H₅−COOH, se usa como conservante en bebidas y alimentos procesados, para evitar el crecimiento de hongos y bacterias.","q":"¿Cuál es el nombre IUPAC del ácido del que proviene esta sal?","o":["ácido benzoico","ácido fenilacético","ácido fenoico","ácido hexanoico"]},{"t":"esteres","c":"exp","af":"E1","ctx":"El jabón, una sal de ácido graso, tiene una «cola» larga de hidrocarburo (apolar) y una «cabeza» con carga negativa (polar), proveniente del grupo −COO⁻.","q":"¿Cómo le permite esa estructura al jabón quitar la grasa de un plato al lavarlo con agua?","o":["La cola apolar se introduce en la grasa y las cabezas polares quedan hacia el agua, de modo que la gota se dispersa y se arrastra con el agua","El jabón reacciona con la grasa y la convierte en agua, que se va por el desagüe junto con la espuma","El jabón reacciona con la grasa y la transforma en sal de cocina, que se disuelve en el agua del lavaplatos","El jabón sube la temperatura del agua y así derrite la grasa del plato hasta que se evapora con el vapor"]},{"t":"esteres","c":"exp","af":"E1","ctx":"El ácido butanoico (88 g/mol) hierve a 164 °C, mientras que el etanoato de etilo (88 g/mol), un éster, hierve a 77 °C.","q":"¿Qué diferencia estructural explica que el éster hierva a una temperatura mucho menor?","o":["El éster no tiene un H unido a oxígeno, así que sus moléculas no forman puentes de hidrógeno entre sí","El éster tiene una masa molar mucho menor que la del ácido, por eso hierve antes","El éster tiene un enlace doble C=C que debilita las fuerzas entre sus moléculas","Los ésteres forman puentes de hidrógeno más fuertes que los ácidos"]},{"t":"acidos","c":"uso","af":"I1","ctx":"El ácido cítrico, presente en el limón y otros cítricos, tiene tres grupos −COOH en su estructura.","q":"¿Cómo se clasifica un ácido con tres grupos carboxilo, según el número de esos grupos?","o":["Triprótico (puede ceder hasta tres H⁺)","Monoprótico","Diprótico","Neutro, porque sus grupos se cancelan entre sí"]},{"t":"acidos","c":"uso","af":"I1","ctx":"La espinaca y el ruibarbo contienen ácido etanodioico (ácido oxálico), HOOC−COOH, que en grandes cantidades puede formar cristales de oxalato de calcio en los riñones.","q":"¿Cuántos grupos −COOH tiene el ácido etanodioico?","o":["Dos","Uno","Tres","Ninguno: es un alcohol"]},{"t":"acidos","c":"uso","af":"I2","ctx":"Observa la siguiente estructura: un anillo de benceno unido a un grupo −CO−Cl.","q":"¿Cuál es su nombre IUPAC?","o":["cloruro de benzoílo","cloruro de bencilo","ácido clorobenzoico","benzoato de cloro"]},{"t":"esteres","c":"uso","af":"I1","ctx":"El aroma de la piña se debe en parte al butanoato de etilo, un éster que también se usa como saborizante artificial.","q":"¿Cuál es su fórmula estructural?","o":["CH₃−CH₂−CH₂−COO−CH₂−CH₃","CH₃−COO−CH₂−CH₂−CH₃","CH₃−CH₂−CH₂−CH₂−COO−CH₃","CH₃−CH₂−COO−CH₂−CH₂−CH₃"]},{"t":"esteres","c":"exp","af":"E1","ctx":"En la esterificación de Fischer (ácido + alcohol → éster + agua), siempre se usa H₂SO₄ o H⁺ como catalizador.","q":"¿Cuál es la función principal del H⁺ en esta reacción?","o":["Protona el grupo carbonilo del ácido, haciéndolo más reactivo para que el alcohol lo ataque","Se incorpora al éster final como parte de su estructura, junto al alcohol","Neutraliza el ácido carboxílico antes de que este reaccione con el alcohol","Rompe el enlace C−C de la cadena del ácido para que entre el alcohol"]},{"t":"acidos","c":"ind","af":"N2","ctx":"Una estudiante mide el pH de tres soluciones 0,1 M: ácido acético, 2,9; ácido clorhídrico, 1,0; etanol, 7,0.","q":"¿Qué conclusión es válida?","o":["El ácido acético es un ácido débil: a la misma concentración libera menos iones H⁺ que el ácido clorhídrico","El ácido acético es más fuerte que el clorhídrico, porque su pH está más cerca de 3","El etanol también es un ácido, aunque su pH de 7 lo hace parecer neutro","Las tres soluciones son igual de ácidas, porque tienen la misma concentración"]},{"t":"acidos","c":"ind","af":"N3","ctx":"Para comprobar que el vinagre contiene un ácido carboxílico, un estudiante le agrega bicarbonato de sodio.","q":"¿Qué observación apoyaría su hipótesis y por qué?","o":["Efervescencia, porque el ácido reacciona con el bicarbonato y libera CO₂","Un cambio a color azul, porque el vinagre es básico","Que no pase nada, porque los ácidos no reaccionan con sales","La formación de un espejo de plata"]},{"t":"acidos","c":"ind","af":"N3","ctx":"Un estudiante quiere comparar la acidez de dos vinagres de distintas marcas. Tiene papel indicador universal y vasos iguales.","q":"¿Qué procedimiento es adecuado?","o":["Medir el pH de volúmenes iguales de cada vinagre, sin diluir, a la misma temperatura","Medir el pH de un vinagre puro y del otro diluido en agua","Probar el sabor de los dos vinagres y decidir cuál es más ácido","Medir el pH de uno solo y compararlo con la etiqueta del otro"]},{"t":"esteres","c":"ind","af":"N2","ctx":"En una práctica de esterificación, se mezclaron ácido etanoico y etanol con unas gotas de ácido sulfúrico y se calentaron; al final apareció un olor a pegante y se formaron dos capas al agregar agua.","q":"¿Qué indican estas observaciones?","o":["Que se formó un éster, poco soluble en agua y de olor característico","Que el ácido etanoico se evaporó y dejó solo el etanol en el tubo","Que se formó una sal muy soluble que se separó en dos capas","Que no hubo reacción, porque el olor viene del ácido sulfúrico"]},{"t":"acidos","c":"ind","af":"N4","ctx":"Una estudiante predice que los ácidos carboxílicos de cadena más larga son menos solubles en agua. Datos: ácido etanoico, en cualquier proporción; butanoico, en cualquier proporción; hexanoico, 1 g/100 mL.","q":"¿Los datos apoyan su predicción?","o":["Sí: el ácido de seis carbonos es mucho menos soluble que los más cortos","No: el ácido butanoico es tan soluble como el etanoico, así que falla","Sí, pero solo si el ácido etanoico fuera el menos soluble de los tres","No: la solubilidad de los ácidos depende solo del grupo −COOH"]},{"t":"esteres","c":"ind","af":"N1","ctx":"Chevreul estudió en el siglo XIX la fabricación del jabón y demostró que las grasas son ésteres de glicerina y ácidos grasos.","q":"¿Qué aportó esta investigación?","o":["Explicó con química un proceso que se usaba desde hacía siglos por tradición","Demostró que el jabón se forma sin ninguna reacción química","Inventó el jabón, que antes no existía en ninguna cultura","Mostró que las grasas son minerales que se disuelven en agua"]},{"t":"acidos","c":"ind","af":"N4","ctx":"Un estudiante consultó el pKa de cuatro ácidos carboxílicos. Cuanto menor es el pKa, más fuerte es el ácido.","q":"¿Qué efecto tienen los átomos de cloro sobre la acidez?","o":["La aumentan: a más cloros, menor pKa y ácido más fuerte","La disminuyen: a más cloros, mayor pKa y ácido más débil","No la cambian, porque el grupo ácido es el mismo","La aumentan solo si el cloro está lejos del grupo ácido"],"tabla":[["Ácido","Cloros","pKa"],["Acético","0","4,76"],["Cloroacético","1","2,87"],["Dicloroacético","2","1,29"],["Tricloroacético","3","0,66"]],"exp":"A más cloros, menor pKa: 4,76; 2,87; 1,29; 0,66. Los cloros atraen electrones y estabilizan el ion carboxilato, así que el ácido cede su H⁺ con más facilidad."},{"t":"aminas","c":"exp","af":"E1","ctx":"Al disolver etanamina en agua, la solución se vuelve básica.","q":"¿Qué explica este comportamiento?","o":["El nitrógeno tiene un par de electrones libre que puede aceptar un H⁺ del agua","El nitrógeno cede con facilidad un H⁺ al agua y la vuelve básica","La etanamina contiene iones OH⁻ en su estructura que pasan al agua","El nitrógeno tiene una carga positiva permanente que atrae al OH⁻"]},{"t":"nitrilos","c":"uso","af":"I1","ctx":"La yuca amarga contiene linamarina, un compuesto con grupo nitrilo (−C≡N) que puede liberar cianuro de hidrógeno (HCN). Antes de consumirla se ralla, se lava y se cocina.","q":"¿Cuál es el propósito de ese procesamiento?","o":["Eliminar el HCN y los compuestos que lo liberan, que son tóxicos","Aumentar la cantidad de nitrilo para mejorar el sabor","Convertir el almidón de la yuca en proteínas","Neutralizar el ácido acético que contiene la yuca"]},{"t":"amidas","c":"uso","af":"I2","ctx":"El paracetamol (acetaminofén), uno de los analgésicos más usados, contiene en su estructura el grupo −NH−CO−.","q":"¿A qué grupo funcional corresponde?","o":["Amida","Amina","Nitrilo","Éster"]},{"t":"aminas","c":"ind","af":"N3","ctx":"El olor del pescado se debe en parte a aminas volátiles. Un estudiante propone la hipótesis: «el jugo de limón reduce el olor porque su ácido reacciona con las aminas y forma sales que no se evaporan».","q":"¿Qué experimento permite poner a prueba esta hipótesis?","o":["Comparar el olor de muestras iguales de pescado tratadas con limón, con agua y sin tratamiento","Agregar limón a todas las muestras de pescado y oler solo una de ellas al final","Cocinar el pescado durante más tiempo sin agregarle nada y comparar el olor","Medir la masa del pescado antes y después de agregarle el jugo de limón"]},{"t":"aminas","c":"exp","af":"E1","ctx":"El olor característico de la carne o el pescado en descomposición se debe en parte a aminas como la cadaverina y la putrescina, que se forman cuando las bacterias degradan proteínas.","q":"¿Por qué estas sustancias se usan como indicador de descomposición en el control de calidad de alimentos?","o":["Porque se forman a partir de aminoácidos de las proteínas a medida que el alimento se descompone, y su concentración aumenta con el tiempo","Porque solo se forman cuando el alimento se congela y descongela varias veces, y desaparecen al cocinarlo","Porque son pigmentos que dan el color rojo a la carne fresca y se pierden cuando el alimento envejece","Porque los fabricantes las agregan como conservantes y su concentración indica cuánto dura el alimento"]},{"t":"amidas","c":"uso","af":"I1","ctx":"En 1828 el químico alemán Friedrich Wöhler sintetizó urea, NH₂−CO−NH₂, a partir de sustancias inorgánicas, lo que ayudó a derribar la idea de que los compuestos orgánicos solo podían formarse dentro de seres vivos.","q":"¿A qué grupo funcional pertenece la urea?","o":["Es una amida (tiene dos grupos −NH₂ unidos a un carbonilo)","Es una amina primaria (tiene un −NH₂ unido a un carbono)","Es un ácido carboxílico (tiene un −COOH)","Es un nitrilo (tiene un −C≡N)"]},{"t":"aminas","c":"ind","af":"N3","ctx":"Las aminas, al ser bases, reaccionan con ácidos como el HCl y forman sales solubles en agua. Esa propiedad se usa para separar aminas de una mezcla con compuestos neutros, como los hidrocarburos.","q":"¿Qué procedimiento permitiría separar una amina de una mezcla con un hidrocarburo, aprovechando esta propiedad?","o":["Agitar la mezcla con HCl diluido: la amina pasa a la fase acuosa como sal y el hidrocarburo queda en la fase orgánica","Calentar la mezcla hasta que hierva toda el agua y quede solamente la amina en el fondo del recipiente","Agregar más hidrocarburo a la mezcla para que la amina se disuelva en él por completo y se pueda decantar","Agregar NaOH concentrado y esperar a que la amina se evapore de la mezcla mientras el hidrocarburo se queda"]},{"t":"aminas","c":"uso","af":"I1","ctx":"La cafeína del café y el té, y la nicotina del tabaco, son alcaloides: compuestos naturales de origen vegetal, en general de carácter básico, con efectos marcados sobre el sistema nervioso.","q":"¿Qué elemento tienen en común todos los alcaloides y es responsable de su carácter básico?","o":["Nitrógeno, con un par de electrones libre que puede aceptar un H⁺","Cloro, que libera iones Cl⁻ en el agua","Azufre, que forma ácido sulfúrico en el agua","Oxígeno, que forma parte de un grupo −COOH"]},{"t":"aminas","c":"exp","af":"E1","ctx":"A masa molar parecida, la etanamina hierve a una temperatura mayor que el propano, pero menor que el etanol.","q":"¿Qué explica esta posición intermedia de la etanamina?","o":["La amina forma puentes de hidrógeno N−H, más débiles que los O−H del alcohol","La etanamina no forma ningún tipo de fuerza entre sus moléculas","El nitrógeno es más electronegativo que el oxígeno y atrae menos","La etanamina tiene una masa molar mucho mayor que la del etanol"]},{"t":"amidas","c":"uso","af":"I2","ctx":"Una amida se puede pensar como el resultado de reemplazar el −OH de un ácido carboxílico por un grupo −NH₂.","q":"¿Cuál es el nombre de la amida que proviene del ácido butanoico?","o":["butanamida","butanamina","ácido butanamídico","butanonitrilo"]},{"t":"amidas","c":"uso","af":"I1","ctx":"Las fibras acrílicas (como el orlón, usado en suéteres y cobijas) se fabrican a partir del monómero acrilonitrilo, CH₂=CH−C≡N.","q":"¿Qué grupos funcionales tiene el acrilonitrilo?","o":["Un doble enlace C=C y un grupo nitrilo (−C≡N)","Un triple enlace C≡C y un grupo amina","Dos grupos nitrilo","Un grupo amida y un grupo alcohol"]},{"t":"amidas","c":"uso","af":"I1","ctx":"El grupo −NH₂ de una amina primaria y el grupo −CO−NH₂ de una amida se confunden con facilidad porque los dos contienen nitrógeno e hidrógeno.","q":"¿Cuál es la diferencia estructural clave entre los dos grupos?","o":["La amida tiene el nitrógeno unido a un carbono carbonilo (C=O); la amina tiene el nitrógeno unido directamente a un carbono de la cadena, sin C=O","La amina tiene el nitrógeno unido a un carbono con doble enlace a oxígeno; la amida tiene el nitrógeno unido a un carbono de la cadena","La amida tiene el nitrógeno unido a un oxígeno (N−O); la amina tiene el nitrógeno unido solo a carbonos e hidrógenos","La amida tiene un triple enlace entre carbono y nitrógeno; la amina tiene un enlace sencillo"]},{"t":"amidas","c":"uso","af":"I2","ctx":"La cadaverina, H₂N−CH₂−CH₂−CH₂−CH₂−CH₂−NH₂, se produce cuando bacterias degradan el aminoácido lisina y es responsable del olor de la materia orgánica en descomposición.","q":"¿Cuál es su nombre IUPAC?","o":["pentano-1,5-diamina","N,N-pentilamina","pentan-1,5-diamida","1,5-diaminopentanol"]},{"t":"amidas","c":"uso","af":"I2","ctx":"La feniletilamina, presente en el chocolate, es un anillo de benceno unido a una cadena de dos carbonos que termina en un grupo −NH₂.","q":"¿Cuál es su nombre IUPAC?","o":["2-feniletan-1-amina","1-feniletan-2-amina","N-fenilamina","feniletanoamida"]},{"t":"aminas","c":"uso","af":"I1","ctx":"Un fragmento de la hormona oxitocina tiene la secuencia Cys-Tyr-Ile-Gln-Asn-Cys-Pro-Leu-Gly (9 residuos de aminoácidos), unidos uno a uno por enlaces peptídicos.","q":"¿Cuántos enlaces peptídicos hay en este fragmento?","o":["8","9","10","7"]},{"t":"amidas","c":"exp","af":"E1","ctx":"La etanamina es una base más fuerte que la anilina (C₆H₅−NH₂), aunque las dos tienen un nitrógeno con un par de electrones libre.","q":"¿Qué explica que la anilina sea una base más débil?","o":["En la anilina el par libre del nitrógeno se deslocaliza hacia el anillo aromático y queda menos disponible para aceptar un H⁺","La anilina no tiene ningún par de electrones libre en el nitrógeno, porque todos forman enlaces con el anillo","La etanamina tiene una carga negativa permanente en el nitrógeno que atrae a los H⁺ del agua","La anilina es en realidad una amida y no una amina, por eso casi no acepta H⁺"]},{"t":"aminas","c":"ind","af":"N2","ctx":"La propilamina y la trimetilamina tienen la misma fórmula molecular, C₃H₉N. La propilamina hierve a 48 °C y la trimetilamina a 3 °C.","q":"¿Qué explicación es coherente con los datos?","o":["La propilamina tiene enlaces N−H y forma puentes de hidrógeno entre sus moléculas; la trimetilamina no tiene hidrógenos unidos al nitrógeno","La trimetilamina tiene más masa molar y por eso sus moléculas se mueven más rápido y hierven antes","Las dos forman los mismos puentes de hidrógeno, pero los de la trimetilamina se rompen con menos energía","La diferencia se debe a que la trimetilamina es un gas a temperatura ambiente y la propilamina no"]},{"t":"aminas","c":"ind","af":"N3","ctx":"Un estudiante cree que las aminas son bases. Tiene papel tornasol rojo y una solución de metilamina en agua.","q":"¿Qué resultado apoyaría su idea?","o":["Que el papel tornasol rojo se vuelva azul","Que el papel tornasol siga rojo","Que se forme un precipitado amarillo","Que la solución empiece a hervir"]},{"t":"aminas","c":"ind","af":"N2","ctx":"Se midió el pH de soluciones 0,1 M: metilamina, 11,8; amoníaco, 11,1; anilina, 8,8.","q":"¿Qué conclusión se apoya en los datos?","o":["La metilamina es la base más fuerte y la anilina la más débil de las tres","La anilina es la base más fuerte porque tiene un anillo aromático","Las tres son ácidos, porque su pH es mayor que 7","Las tres tienen la misma fuerza básica, porque todas tienen nitrógeno"]},{"t":"aminas","c":"ind","af":"N3","ctx":"Un grupo quiere saber si el olor a pescado disminuye al agregar vinagre. Tienen muestras iguales de pescado fresco.","q":"¿Qué diseño es adecuado?","o":["Tratar unas muestras con vinagre y otras con agua, y comparar el olor con varias personas que no saben cuál es cuál","Tratar todas las muestras con vinagre y preguntar a una persona si huelen menos","Tratar unas muestras con vinagre y otras con limón, y oler solo las de limón","Oler el pescado antes de comprarlo y compararlo con el de la casa"]},{"t":"aminas","c":"ind","af":"N4","ctx":"Un estudiante predice que la urea, al calentarse con NaOH, libera amoníaco. Acerca papel tornasol rojo húmedo a la boca del tubo y el papel se vuelve azul.","q":"¿Qué se puede decir de su predicción?","o":["La observación la apoya: se liberó un gas básico como el amoníaco","La observación la refuta: el papel azul indica un gas ácido","No se puede evaluar, porque el tornasol no reacciona con gases","La observación la apoya solo si el papel se hubiera vuelto rojo"]},{"t":"aminas","c":"ind","af":"N4","ctx":"Un estudiante consultó el pKb de cuatro bases nitrogenadas. Cuanto menor es el pKb, más fuerte es la base.","q":"¿Qué muestran los datos sobre la anilina?","o":["Es la base más débil, porque el par de electrones del N se comparte con el anillo","Es la base más fuerte, porque tiene un anillo aromático unido al nitrógeno","Es tan básica como la metilamina, porque las dos tienen nitrógeno en su estructura","No es una base, porque su valor de pKb es mayor que el del amoníaco"],"tabla":[["Compuesto","pKb"],["Amoníaco","4,75"],["Metilamina","3,36"],["Dimetilamina","3,27"],["Anilina","9,37"]],"exp":"Menor pKb significa base más fuerte: la dimetilamina (3,27) es la más fuerte y la anilina (9,37) la más débil. En la anilina el par de electrones del nitrógeno se reparte con el anillo y queda menos disponible para aceptar H⁺."},{"t":"polifuncionales","c":"exp","af":"E1","ctx":"Una molécula tiene un grupo −OH y un grupo −CHO.","q":"¿Cuál de los dos da el sufijo del nombre y por qué?","o":["El −CHO, porque el aldehído tiene mayor prioridad que el alcohol; el −OH se nombra con el prefijo hidroxi-","El −OH, porque está más cerca del extremo de la cadena y siempre se numera primero","El que aparezca primero al leer la fórmula de izquierda a derecha, sin importar el grupo","Ambos, porque cuando hay dos grupos funcionales se nombran siempre los dos como sufijos"]},{"t":"polifuncionales","c":"uso","af":"I2","ctx":"La alanina, uno de los aminoácidos de las proteínas, es CH₃−CH(NH₂)−COOH.","q":"¿Cuál es su nombre sistemático?","o":["ácido 2-aminopropanoico","ácido 3-aminopropanoico","2-aminopropan-1-ol","1-carboxietan-1-amina"]},{"t":"polifuncionales","c":"exp","af":"E1","ctx":"La glucosa (C₆H₁₂O₆), en su forma de cadena abierta, tiene cinco grupos −OH y un grupo aldehído. Se disuelve muy bien en agua, mientras que el hexano (C₆H₁₄) no.","q":"¿Qué explica la diferencia?","o":["Los grupos −OH de la glucosa forman puentes de hidrógeno con el agua; el hexano es apolar","La glucosa tiene más átomos de carbono que el hexano y por eso se disuelve","El hexano reacciona con el agua y se descompone en gases antes de disolverse","La glucosa es un compuesto iónico, como la sal de cocina, y se separa en iones"]},{"t":"polifuncionales","c":"ind","af":"N2","ctx":"Un grupo quiere saber qué grupo funcional del ácido láctico (el −OH o el −COOH) es el responsable de su acidez.","q":"¿Qué comparación es la más útil?","o":["Medir el pH de soluciones de igual concentración de ácido láctico, propan-2-ol y ácido propanoico","Medir la temperatura de ebullición del ácido láctico y compararla con la del agua","Comparar el color de soluciones de ácido láctico y de glucosa de igual concentración","Medir el pH del agua destilada sola en días diferentes y promediar los valores"]},{"t":"polifuncionales","c":"uso","af":"I1","ctx":"La adrenalina (epinefrina), una hormona que el cuerpo libera en situaciones de estrés o peligro, tiene en su estructura un anillo aromático con dos grupos −OH, otro −OH en la cadena lateral y un grupo amina.","q":"¿Qué grupos funcionales con oxígeno o nitrógeno identificas en esta descripción?","o":["Grupos hidroxilo (−OH) y un grupo amina","Grupos hidroxilo (−OH) y un grupo amida","Grupos carbonilo (C=O) y un grupo amina","Grupos hidroxilo (−OH), un grupo amina y un ácido carboxílico"]},{"t":"polifuncionales","c":"exp","af":"E1","ctx":"El orden de prioridad IUPAC para elegir el sufijo principal es, de mayor a menor: ácido carboxílico, éster, amida, nitrilo, aldehído, cetona, alcohol, amina.","q":"Si una molécula tiene un grupo amina y un grupo cetona, ¿cuál de los dos da la terminación del nombre?","o":["La cetona, porque tiene mayor prioridad que la amina; la amina se nombra entonces como prefijo amino-","La amina, porque el nitrógeno tiene mayor prioridad que el oxígeno en la nomenclatura","Ninguno de los dos: cuando hay dos grupos, los dos se nombran siempre como prefijos","Depende de cuál de los dos grupos esté más cerca del extremo de la cadena principal"]},{"t":"polifuncionales","c":"uso","af":"I2","ctx":"El GABA (ácido gamma-aminobutírico), el principal neurotransmisor inhibidor del sistema nervioso, tiene la estructura H₂N−CH₂−CH₂−CH₂−COOH.","q":"¿Cuál es su nombre sistemático (IUPAC)?","o":["ácido 4-aminobutanoico","ácido 2-aminobutanoico","ácido 1-aminobutanoico","butanoato de amonio"]},{"t":"polifuncionales","c":"ind","af":"N2","ctx":"Una molécula desconocida decolora el agua de bromo con rapidez (prueba de alqueno) pero no reacciona con el reactivo de Tollens (prueba de aldehído). Se sabe que tiene un doble enlace C=C y un grupo carbonilo.","q":"¿Qué se puede concluir sobre el grupo carbonilo de esta molécula?","o":["Es una cetona y no un aldehído, porque no dio positiva la prueba de Tollens","Es un aldehído, porque decoloró el agua de bromo","La molécula no tiene ningún grupo carbonilo","La molécula es un alcano, porque no reaccionó con Tollens"]},{"t":"polifuncionales","c":"exp","af":"E1","ctx":"La pentano-2,4-diona tiene dos grupos cetona, ambos del mismo tipo.","q":"¿Por qué el nombre lleva el sufijo «-diona» con dos localizadores (2,4) en vez de nombrarse como si tuviera un solo grupo principal?","o":["Porque cuando hay dos o más grupos iguales de la máxima prioridad, todos se incluyen en el sufijo, cada uno con su propio localizador","Porque solo el grupo de menor localizador es el principal, y el otro debería nombrarse con el prefijo oxo-","Porque las cetonas se nombran como dos alcanos unidos por un C=O, y cada uno aporta un localizador","Porque el localizador 4 indica la longitud de la cadena y no la posición del segundo grupo"]},{"t":"polifuncionales","c":"uso","af":"I2","ctx":"La serina, otro aminoácido de las proteínas, tiene en su estructura un grupo amina, un grupo ácido carboxílico y además un grupo hidroxilo: HO−CH₂−CH(NH₂)−COOH.","q":"De los tres grupos funcionales que tiene la serina, ¿cuál da la terminación del nombre, según el orden de prioridad IUPAC?","o":["El ácido carboxílico (−COOH): termina en «-oico», y los otros dos se nombran como prefijos (amino-, hidroxi-)","El grupo amina, porque el nitrógeno tiene prioridad sobre el oxígeno en la nomenclatura","El grupo hidroxilo, porque está en el extremo de la cadena y se numera con el 1","Los tres compiten por igual y el nombre se escoge según el que tenga más átomos"]},{"t":"polifuncionales","c":"exp","af":"E3","ctx":"El ácido tartárico, presente en la uva y usado en la industria de alimentos, tiene dos grupos −COOH y dos grupos −OH en una cadena de solo 4 carbonos.","q":"¿Cómo se nombran los grupos −OH en el nombre de este ácido, ya que no son el grupo de mayor prioridad?","o":["Como prefijos hidroxi-, cada uno con su propio localizador","Como sufijos -ol adicionales al final del nombre","Se ignoran por completo en el nombre","Reemplazan a los grupos −COOH en el nombre final"]},{"t":"polifuncionales","c":"uso","af":"I1","ctx":"El herbicida 2,4-D (ácido 2,4-diclorofenoxiacético), uno de los más usados en el mundo contra malezas de hoja ancha, tiene un anillo de benceno con dos cloros, unido mediante un oxígeno a una cadena −CH₂−COOH.","q":"¿Qué dos grupos funcionales tiene esta molécula, además del anillo aromático y los cloros?","o":["Un éter (el oxígeno que conecta el anillo con la cadena) y un ácido carboxílico","Un éter que une el anillo con la cadena y un grupo aldehído","Un alcohol unido al anillo y un ácido carboxílico al final","Un éster entre el anillo y la cadena y un grupo fenol"]},{"t":"polifuncionales","c":"uso","af":"I1","ctx":"El ácido acetilsalicílico (aspirina) tiene un anillo aromático con un grupo −COOH y, en el carbono vecino, un grupo éster (−O−CO−CH₃).","q":"¿Cuáles son sus dos grupos funcionales con oxígeno, aparte del anillo?","o":["Un ácido carboxílico y un éster","Un alcohol y un éster","Dos grupos ácido carboxílico","Un aldehído y un ácido carboxílico"]},{"t":"polifuncionales","c":"exp","af":"E1","ctx":"El orden de prioridad IUPAC ya visto es: ácido carboxílico > éster > amida > nitrilo > aldehído > cetona > alcohol > amina.","q":"Si una molécula tiene un grupo nitrilo y un grupo cetona, ¿cuál de los dos da la terminación del nombre?","o":["El nitrilo, porque tiene mayor prioridad que la cetona; la cetona se nombra entonces con el prefijo oxo-","La cetona, porque el oxígeno tiene prioridad sobre el nitrógeno en la nomenclatura","Ninguno: cuando hay dos grupos, los dos se nombran siempre como sufijos a la vez","Depende de cuál de los dos grupos esté más cerca del extremo de la cadena principal"]},{"t":"polifuncionales","c":"ind","af":"N2","ctx":"La glucosa, C₆H₁₂O₆, tiene cinco grupos −OH y un grupo carbonilo, y se disuelve fácilmente en agua. El hexano, C₆H₁₄, también tiene seis carbonos, pero no se disuelve en agua.","q":"¿Qué conclusión se apoya en esta información?","o":["Los grupos −OH de la glucosa forman puentes de hidrógeno con el agua y la hacen soluble","La glucosa es soluble porque tiene seis carbonos, igual que el hexano","El hexano tiene más grupos −OH que la glucosa, pero están ocultos","La solubilidad no depende de los grupos funcionales sino del tamaño"]},{"t":"polifuncionales","c":"ind","af":"N2","ctx":"Una muestra desconocida forma un espejo de plata con el reactivo de Tollens y produce efervescencia al agregarle bicarbonato de sodio.","q":"¿Qué grupos funcionales podría tener la muestra?","o":["Un aldehído y un ácido carboxílico","Solo un alcohol","Una cetona y un éter","Ningún grupo funcional: es un alcano"]},{"t":"polifuncionales","c":"ind","af":"N3","ctx":"Una estudiante quiere saber si la vitamina C de un jugo se destruye al hervirlo. Tiene jugo, solución de yodo con almidón y un gotero.","q":"¿Qué procedimiento es adecuado?","o":["Comparar cuántas gotas de jugo crudo y de jugo hervido quitan el color a la misma cantidad de solución","Hervir el jugo y contar las gotas, sin comparar con el jugo sin hervir","Comparar el color del jugo crudo y del jugo hervido a simple vista","Agregar más solución de yodo al jugo hervido que al jugo crudo"]},{"t":"polifuncionales","c":"ind","af":"N2","ctx":"La glicina, el aminoácido más sencillo, funde a 233 °C; el ácido acético, de masa parecida, funde a 17 °C.","q":"¿Qué explicación es coherente con los datos?","o":["La glicina forma iones dipolares que se atraen con fuerza, como en un sólido iónico","La glicina tiene más carbonos que el ácido acético y por eso funde más alto","El ácido acético forma iones y la glicina no, por eso funde a menor temperatura","La diferencia se debe a errores de medición, porque sus masas son parecidas"]},{"t":"polifuncionales","c":"ind","af":"N4","ctx":"Un grupo predice que el ácido láctico de la leche agria tiene un grupo ácido. Al agregar bicarbonato a la leche agria se observan burbujas.","q":"¿Los resultados apoyan su predicción?","o":["Sí: las burbujas de CO₂ indican la presencia de un ácido","No: las burbujas indican que la leche tiene un aldehído","Sí, pero solo si también se hubiera formado un espejo de plata","No: el bicarbonato hace burbujas con cualquier líquido"]},{"t":"polifuncionales","c":"ind","af":"N1","ctx":"El químico Linus Pauling propuso que las cadenas de aminoácidos forman hélices estables gracias a puentes de hidrógeno, y años después se confirmó con rayos X.","q":"¿Qué muestra este ejemplo?","o":["Que una predicción basada en un modelo puede comprobarse luego con evidencia experimental","Que los modelos de moléculas no necesitan ninguna comprobación experimental","Que los rayos X refutaron la idea de los puentes de hidrógeno en las proteínas","Que las proteínas no tienen estructura y se mueven al azar en las células"]},{"t":"isomeria","c":"uso","af":"I1","ctx":"Los alcanos de fórmula C₅H₁₂ pueden tener la cadena lineal o ramificada.","q":"¿Cuántos isómeros estructurales tiene el C₅H₁₂?","o":["3","2","4","5"]},{"t":"isomeria","c":"uso","af":"I1","ctx":"La talidomida se recetó en los años 50 y 60 a mujeres embarazadas; se ha asociado a uno de sus enantiómeros con las malformaciones (aunque en el cuerpo se transforman uno en otro).","q":"¿Qué tienen en común dos enantiómeros?","o":["La misma fórmula y los mismos enlaces, pero son imágenes especulares que no se superponen","Tienen fórmulas moleculares diferentes, aunque sus nombres sean parecidos","Tienen grupos funcionales diferentes que cambian su efecto en el cuerpo","Son la misma estructura superponible, vendida con dos nombres comerciales"]},{"t":"isomeria","c":"exp","af":"E1","ctx":"Las grasas trans se forman en la hidrogenación parcial de aceites vegetales y su consumo aumenta el riesgo cardiovascular.","q":"¿En qué se diferencia un ácido graso trans de su isómero cis?","o":["En la disposición de los grupos alrededor del doble enlace: en el trans quedan en lados opuestos","En que el trans tiene el doble enlace en otra posición de la cadena","En que el trans tiene un carbono más en la cadena principal","En que el trans tiene un grupo funcional diferente al del cis"]},{"t":"isomeria","c":"ind","af":"N3","ctx":"En el laboratorio hay dos recipientes rotulados «C₄H₁₀». Se sospecha que uno contiene butano y el otro 2-metilpropano.","q":"¿Qué medición permite comprobar que son sustancias distintas?","o":["Comparar sus puntos de ebullición en las mismas condiciones","Comparar sus fórmulas moleculares en un libro","Contar los átomos de carbono de cada uno","Comparar la masa molar de cada uno en la tabla"]},{"t":"isomeria","c":"uso","af":"I1","ctx":"El C₄H₁₀ puede tener la cadena lineal o ramificada.","q":"¿Cuántos isómeros estructurales (de cadena) tiene el C₄H₁₀?","o":["2","1","3","4"]},{"t":"isomeria","c":"uso","af":"I1","ctx":"El C₆H₁₄ se puede ramificar de varias formas: sin ramificar, con un metilo en distintas posiciones, con dos metilos, etc.","q":"¿Cuántos isómeros estructurales tiene el C₆H₁₄?","o":["5","3","4","6"]},{"t":"isomeria","c":"exp","af":"E3","ctx":"El aceite de oliva, rico en ácido oleico (un ácido graso cis), es líquido a temperatura ambiente. El ácido elaídico, su isómero trans, forma parte de grasas que son sólidas o semisólidas a esa misma temperatura.","q":"¿Qué explica esta diferencia en el punto de fusión entre los dos isómeros?","o":["La forma doblada de la cadena cis impide que las moléculas se empaqueten tan ordenadamente como las del isómero trans, de forma más recta","La cadena trans está doblada y por eso sus moléculas se empaquetan peor que las del isómero cis","El ácido cis forma puentes de hidrógeno entre sus cadenas y el trans no puede formarlos","Los isómeros cis y trans tienen fórmulas moleculares diferentes y por eso distinta masa"]},{"t":"isomeria","c":"ind","af":"N2","ctx":"Un grupo tiene dos frascos sin etiqueta, ambos con un líquido de fórmula C₄H₁₀O: se sospecha que uno es butan-1-ol y el otro, etoxietano (un éter).","q":"¿Qué propiedad permitiría distinguirlos con más seguridad?","o":["El punto de ebullición: el alcohol, que forma puentes de hidrógeno, hierve mucho más alto que el éter","El color del líquido: el alcohol es incoloro y el éter amarillento","El olor de cada líquido, porque los alcoholes no tienen ningún olor","La fórmula molecular, que permite saber cuál grupo funcional tiene cada uno"]},{"t":"isomeria","c":"uso","af":"I1","ctx":"Las dos manos de una persona son parecidas pero no idénticas: son imágenes especulares entre sí y no se pueden superponer exactamente, igual que los dos enantiómeros de una molécula quiral.","q":"¿Qué característica deben tener los cuatro grupos unidos a un carbono para que ese carbono sea quiral?","o":["Los cuatro grupos deben ser diferentes entre sí","Los cuatro grupos deben ser iguales","Solo dos de los cuatro grupos deben ser diferentes","El carbono debe tener un doble enlace"]},{"t":"isomeria","c":"uso","af":"I2","ctx":"El pentano, el 2-metilbutano y el 2,2-dimetilpropano tienen los tres la fórmula molecular C₅H₁₂, pero esqueletos de carbono distintos.","q":"¿Qué tipo de isómeros son entre sí?","o":["Isómeros de cadena","Isómeros de posición","Isómeros de función","Isómeros cis/trans"]},{"t":"isomeria","c":"exp","af":"E1","ctx":"El limoneno es un compuesto quiral: uno de sus enantiómeros huele a naranja y el otro, a pino o trementina, aunque los dos tienen exactamente la misma fórmula molecular y los mismos enlaces.","q":"¿Por qué el cuerpo humano puede distinguir el olor de dos enantiómeros tan parecidos químicamente?","o":["Los receptores olfativos son moléculas quirales y reconocen de forma distinta cada una de las dos formas especulares","Porque los dos enantiómeros tienen fórmulas moleculares distintas aunque se parezcan mucho","Porque uno de los dos enantiómeros no tiene átomos de carbono y huele a otra cosa","Porque el olor no depende de la estructura química, sino del color de cada sustancia"]},{"t":"isomeria","c":"uso","af":"I2","ctx":"El 1-clorobutano y el 2-clorobutano tienen la misma fórmula molecular, C₄H₉Cl, pero el cloro está en una posición distinta de la cadena.","q":"¿Qué tipo de isómeros son?","o":["Isómeros de posición","Isómeros de cadena","Isómeros de función","Isómeros cis/trans"]},{"t":"isomeria","c":"uso","af":"I2","ctx":"El 1,2-diclorobenceno y el 1,4-diclorobenceno tienen la misma fórmula molecular, C₆H₄Cl₂, pero los dos átomos de cloro ocupan posiciones distintas del anillo.","q":"¿Qué tipo de isómeros son?","o":["De posición","De cadena","De función","Cis/trans"]},{"t":"isomeria","c":"uso","af":"I1","ctx":"El heptano, C₇H₁₆, puede tener la cadena lineal o varias formas ramificadas.","q":"¿Cuántos isómeros estructurales tiene el C₇H₁₆?","o":["9","5","7","12"]},{"t":"isomeria","c":"exp","af":"E1","ctx":"El hex-3-eno, CH₃−CH₂−CH=CH−CH₂−CH₃, tiene un doble enlace entre el C3 y el C4.","q":"¿Tiene isomería cis/trans?","o":["Sí, porque cada carbono del doble enlace está unido a un H y a un grupo etilo, dos sustituyentes distintos","No, porque los dos lados de la molécula son iguales y eso impide la isomería","No, porque el doble enlace no está en el centro exacto de la cadena","Sí, pero solo existe la forma cis, porque la trans es inestable"]},{"t":"isomeria","c":"ind","af":"N2","ctx":"El etanol y el dimetiléter tienen la misma fórmula molecular, C₂H₆O. El etanol hierve a 78 °C y reacciona con sodio liberando hidrógeno; el dimetiléter hierve a −24 °C y no reacciona con sodio.","q":"¿Qué conclusión se apoya en estos datos?","o":["Son isómeros de función: la misma fórmula molecular con distinta estructura da propiedades distintas","Son la misma sustancia con dos nombres, medida en condiciones distintas","Tienen distinta fórmula molecular, aunque se escriban parecido","La fórmula molecular determina todas las propiedades de una sustancia"]},{"t":"isomeria","c":"ind","af":"N3","ctx":"El limoneno tiene dos formas que son imágenes especulares: una huele a naranja y la otra a limón. Las dos tienen el mismo punto de ebullición y la misma densidad.","q":"¿Qué medición permite distinguirlas en el laboratorio?","o":["El sentido en que desvía cada una la luz polarizada","El punto de ebullición de cada una","La densidad de cada una a 20 °C","La fórmula molecular de cada una"]},{"t":"isomeria","c":"ind","af":"N3","ctx":"Un grupo tiene dos líquidos con fórmula C₃H₈O: propan-1-ol y propan-2-ol. Quiere distinguirlos con un experimento sencillo.","q":"¿Qué procedimiento es adecuado?","o":["Oxidarlos con dicromato y probar el producto con Tollens: solo el del alcohol primario da espejo de plata","Medir la masa molar de cada uno, porque los dos isómeros tienen masas distintas","Contar los átomos de oxígeno de cada fórmula molecular para ver cuál tiene más","Agregar agua a los dos y ver cuál se mezcla, porque solo uno de ellos es soluble"]},{"t":"isomeria","c":"ind","af":"N2","ctx":"Puntos de ebullición de tres isómeros C₆H₁₄: hexano 69 °C; 3-metilpentano 63 °C; 2,2-dimetilbutano 50 °C.","q":"¿Qué conclusión es coherente con los datos?","o":["A más ramificación, menor contacto entre moléculas y menor punto de ebullición","A más ramificación, mayor masa molar y mayor punto de ebullición","La ramificación no influye, porque los tres tienen la misma fórmula","El hexano hierve más alto porque tiene más átomos de carbono que los otros"]},{"t":"isomeria","c":"ind","af":"N4","ctx":"Un estudiante predice que el ácido maleico (cis) y el ácido fumárico (trans) tienen puntos de fusión distintos. Consulta: maleico 135 °C; fumárico 287 °C.","q":"¿Qué se puede decir de su predicción?","o":["Los datos la apoyan: la forma geométrica cambia el punto de fusión","Los datos la refutan: los dos son ácidos y deberían fundir igual","No se puede evaluar, porque los isómeros cis/trans son la misma sustancia","Los datos la apoyan solo si el isómero cis fundiera a mayor temperatura"]},{"t":"isomeria","c":"ind","af":"N4","ctx":"Un grupo comparó los puntos de ebullición de tres alcoholes que tienen la misma fórmula molecular, C₄H₁₀O, pero distinta ramificación.","q":"¿Qué relación hay entre la ramificación y el punto de ebullición?","o":["A más ramificación, menor punto de ebullición, porque hay menos contacto entre moléculas","A más ramificación, mayor punto de ebullición, porque hay más enlaces","La ramificación no influye porque la fórmula molecular es igual","A más ramificación, menor masa molar y por eso hierve a menor temperatura"],"tabla":[["Alcohol","Ramificación","Punto de ebullición (°C)"],["1-butanol","Ninguna","118"],["2-butanol","Una","99"],["2-metil-2-propanol","Dos","83"]],"exp":"Los tres alcoholes tienen la misma fórmula, así que la diferencia viene de la forma: 118, 99 y 83 °C. Cuantas más ramas, más compacta la molécula, menos contacto entre ellas y fuerzas de London más débiles."},{"t":"rxn_derivados","c":"uso","af":"I2","ctx":"CH₂=CH₂ + H₂O → CH₃−CH₂−OH (con H₂SO₄ como catalizador)","q":"¿Qué tipo de reacción es?","o":["Adición","Sustitución","Eliminación","Esterificación"]},{"t":"rxn_alquenos","c":"uso","af":"I2","ctx":"CH₃−CH₂−OH → CH₂=CH₂ + H₂O (con H₂SO₄ concentrado y calor)","q":"¿Qué tipo de reacción es?","o":["Eliminación (deshidratación)","Adición (hidratación)","Sustitución nucleofílica","Combustión"]},{"t":"rxn_alquenos","c":"ind","af":"N2","ctx":"En la preparación tradicional de la chicha y el guarapo, las levaduras transforman azúcares en etanol: C₆H₁₂O₆ → 2 C₂H₅OH + 2 CO₂.","q":"¿Qué observación indica que esta reacción está ocurriendo?","o":["El desprendimiento de burbujas de gas en la mezcla","La aparición de un espejo de plata en el recipiente","El cambio de la mezcla a un color azul intenso","La formación de un sólido blanco cuando la mezcla se enfría"]},{"t":"rxn_derivados","c":"uso","af":"I1","ctx":"CH₃−COOH + CH₃−OH ⇌ ? + H₂O (con H₂SO₄ como catalizador)","q":"¿Cuál es el producto orgánico de esta esterificación?","o":["etanoato de metilo","metanoato de etilo","etanoato de etilo","metoxietano"]},{"t":"rxn_alcanos","c":"exp","af":"E1","ctx":"En la cloración del metano con luz, el enlace Cl−Cl se rompe de modo que cada átomo de cloro se queda con uno de los dos electrones del enlace.","q":"¿Cómo se llama este tipo de ruptura y qué especies forma?","o":["Ruptura homolítica; se forman radicales libres","Ruptura heterolítica; se forman los iones Cl⁺ y Cl⁻","Ruptura homolítica; se forman carbocationes","Ruptura heterolítica; se forman radicales libres"]},{"t":"rxn_derivados","c":"ind","af":"N2","ctx":"Para estudiar cómo influye la temperatura en la rapidez de la esterificación, un grupo mezcla ácido etanoico, etanol y H₂SO₄ en tres tubos que mantiene a 20 °C, 40 °C y 60 °C.","q":"¿Qué deben mantener igual en los tres tubos?","o":["Las cantidades de reactivos y de catalizador, y el tiempo de reacción","La temperatura de los tres tubos, para que solo cambie el catalizador","Solamente el tamaño de los tubos, porque las cantidades no importan","Nada: cada tubo puede tener cantidades diferentes de reactivos"]},{"t":"rxn_alquenos","c":"uso","af":"I2","ctx":"CH≡CH + 2 H₂ → CH₃−CH₃ (con catalizador de Ni o Pt)","q":"¿Qué tipo de reacción es?","o":["Adición (hidrogenación)","Sustitución","Eliminación","Oxidación"]},{"t":"rxn_derivados","c":"uso","af":"I2","ctx":"CH₃−CH₂−Br + NaOH (en agua) → CH₃−CH₂−OH + NaBr","q":"¿Qué tipo de reacción es?","o":["Sustitución nucleofílica","Adición electrofílica","Eliminación","Esterificación"]},{"t":"rxn_derivados","c":"exp","af":"E1","ctx":"La elaboración tradicional de jabón consiste en calentar grasa o aceite con una solución concentrada de NaOH (soda cáustica).","q":"¿Qué tipo de reacción convierte la grasa (un éster) en jabón (una sal de ácido graso) y glicerina?","o":["Hidrólisis básica (saponificación): el NaOH rompe el enlace éster de la grasa","Esterificación: el NaOH forma un nuevo éster con la grasa","Combustión: la grasa se oxida por completo con el calor","Adición: el NaOH se suma a un doble enlace de la grasa"]},{"t":"rxn_derivados","c":"uso","af":"I2","ctx":"CH₃−CH₂−CHBr−CH₃ + KOH (en etanol, con calor) → CH₃−CH=CH−CH₃ + KBr + H₂O","q":"¿Qué tipo de reacción es?","o":["Eliminación","Adición","Sustitución nucleofílica","Esterificación"]},{"t":"rxn_derivados","c":"ind","af":"N2","ctx":"En la producción de biodiésel a partir de aceite de palma y metanol (con un catalizador básico), al terminar la reacción la mezcla se separa en dos capas: una de biodiésel (ésteres metílicos) y otra, más densa, de glicerina.","q":"¿Qué evidencia confirma que ocurrió la transesterificación y no solo una mezcla física de aceite y metanol?","o":["La aparición de glicerina como subproducto, que no estaba presente en los reactivos originales","Que el aceite y el metanol forman una sola capa uniforme al agitarlos con fuerza","Que el aceite cambia de color, de anaranjado a amarillo, al mezclarse con el metanol","Que la mezcla se calienta un poco al agitarla, como pasa con cualquier reacción"]},{"t":"rxn_derivados","c":"uso","af":"I1","ctx":"CH₃−CH₂−COOH + CH₃−CH₂−OH ⇌ ? + H₂O (con H₂SO₄ como catalizador)","q":"¿Cuál es el producto orgánico principal de esta esterificación?","o":["propanoato de etilo","etanoato de propilo","propanoato de metilo","ácido etanoico"]},{"t":"rxn_alquenos","c":"uso","af":"I2","ctx":"CH₂=CH−CH₃ + HCl → CH₃−CHCl−CH₃ (producto principal)","q":"¿Qué tipo de reacción es?","o":["Adición electrofílica","Sustitución nucleofílica","Eliminación","Condensación"]},{"t":"rxn_alcoholes","c":"exp","af":"E1","ctx":"El etanol carburante que se mezcla con la gasolina en Colombia se produce en el Valle del Cauca fermentando el azúcar de la caña con levaduras, en tanques cerrados.","q":"¿Por qué esta reacción se clasifica como una fermentación y no simplemente como una combustión?","o":["Porque ocurre por la acción de microorganismos (levaduras) y sin necesidad de oxígeno del aire, a diferencia de la combustión","Porque libera la misma cantidad de energía que una combustión, pero en tanques cerrados","Porque libera más energía que una combustión y necesita levaduras para controlarla","Porque ocurre a temperatura alta, con llama, y sus productos son solo gases"]},{"t":"rxn_derivados","c":"exp","af":"E1","ctx":"En la esterificación entre un ácido carboxílico y un alcohol, el H₂SO₄ acelera la reacción, pero al final se recupera en la misma cantidad con la que se agregó.","q":"¿Qué papel cumple el H₂SO₄ en esta reacción?","o":["Actúa como catalizador: acelera la reacción sin consumirse en el proceso","Actúa como reactivo: se consume y forma parte del éster final","Actúa únicamente como disolvente del ácido y del alcohol","Actúa como producto: se forma junto con el éster y el agua"]},{"t":"rxn_alquenos","c":"ind","af":"N3","ctx":"Un grupo quiere saber si el agua de bromo se decolora más rápido cuando hay más alqueno. Usa dos tubos con la misma cantidad de agua de bromo, a la misma temperatura; en uno pone 1 mL de ciclohexeno y en el otro, 3 mL.","q":"¿Qué variable cambian a propósito y qué deben medir?","o":["Cambian la cantidad de ciclohexeno y deben medir el tiempo que tarda en desaparecer el color del bromo","Cambian la temperatura y deben medir la cantidad de ciclohexeno que queda","Cambian la cantidad de agua de bromo y deben medir el volumen final","Cambian el tipo de alqueno y deben medir la masa de cada tubo"]},{"t":"rxn_alquenos","c":"uso","af":"I2","ctx":"CH₃−CH₂−OH → CH₃−CHO (con un oxidante suave y controlado)","q":"¿Qué tipo de reacción es, respecto al carbono que lleva el −OH?","o":["Oxidación: ese carbono gana un enlace con oxígeno y pierde un enlace con hidrógeno","Reducción: ese carbono gana un enlace con hidrógeno y pierde uno con oxígeno","Sustitución: el −OH es reemplazado por un átomo de hidrógeno","Eliminación: se pierde agua y se forma un doble enlace C=C"]},{"t":"rxn_aromaticos","c":"uso","af":"I2","ctx":"C₆H₆ + HNO₃ → C₆H₅−NO₂ + H₂O (con H₂SO₄ como catalizador)","q":"¿Qué tipo de reacción es?","o":["Sustitución electrofílica aromática","Adición electrofílica al anillo","Eliminación de agua del anillo","Sustitución nucleofílica en el anillo"]},{"t":"rxn_derivados","c":"uso","af":"I2","ctx":"CH₃−CO−NH₂ + H₂O (con H⁺ y calor) → CH₃−COOH + NH₄⁺","q":"¿Qué tipo de reacción es?","o":["Hidrólisis de una amida","Esterificación","Saponificación","Deshidratación"]},{"t":"rxn_carbonilo","c":"uso","af":"I2","ctx":"CH₃−CO−CH₃ + NaBH₄ (y luego agua) → CH₃−CH(OH)−CH₃","q":"¿Qué tipo de reacción es, respecto al carbono del grupo carbonilo?","o":["Reducción: ese carbono gana un enlace con hidrógeno y pierde uno con oxígeno","Oxidación: ese carbono gana un enlace con oxígeno","Sustitución nucleofílica: el oxígeno es reemplazado por hidrógeno","Eliminación: se pierde agua y se forma un doble enlace"]},{"t":"rxn_alquenos","c":"uso","af":"I2","ctx":"CH₃−CH₂−Br + NaCN → CH₃−CH₂−C≡N + NaBr","q":"¿Qué tipo de reacción es?","o":["Sustitución nucleofílica","Adición nucleofílica","Eliminación","Oxidación"]},{"t":"rxn_alcoholes","c":"ind","af":"N2","ctx":"Se quemó la misma masa de etanol en tres mecheros con distinta entrada de aire. Con poco aire la llama fue amarilla y dejó hollín; con mucho aire la llama fue azul y no dejó hollín.","q":"¿Qué conclusión es válida?","o":["Con poco oxígeno la combustión es incompleta y produce hollín (carbono) y CO; con suficiente oxígeno es completa","La cantidad de aire no influye: el color de la llama depende del mechero","El hollín indica que la combustión fue completa y aprovechó todo el carbono","La llama azul indica falta de oxígeno y la amarilla, exceso de oxígeno"]},{"t":"rxn_derivados","c":"ind","af":"N3","ctx":"Una estudiante quiere saber si unas gotas de ácido sulfúrico aceleran la esterificación del ácido acético con etanol.","q":"¿Qué diseño le permite saberlo?","o":["Preparar dos mezclas iguales de ácido y alcohol a la misma temperatura, una con ácido sulfúrico y otra sin él, y comparar cuánto éster se forma en el mismo tiempo","Preparar una sola mezcla con ácido sulfúrico, medir cuánto éster se forma en una hora y compararlo con el valor del libro","Preparar una segunda mezcla en la que se cambien al mismo tiempo el alcohol y el catalizador, y comparar las dos","Calentar solo la mezcla que no tiene catalizador, para que las dos reaccionen a la misma velocidad, y luego compararlas"]},{"t":"rxn_alcoholes","c":"ind","af":"N4","ctx":"Una estudiante predice que la combustión del etanol produce agua. Pone un vaso frío boca abajo sobre la llama y ve que se empaña con gotas.","q":"¿Qué se puede decir de su predicción?","o":["La observación la apoya: el vapor de agua de la combustión se condensó en el vaso","La observación la refuta: las gotas vienen del aire y no de la combustión","No se puede evaluar, porque la combustión solo produce dióxido de carbono","La observación la apoya solo si las gotas fueran de etanol sin quemar"]},{"t":"rxn_alcanos","c":"ind","af":"N1","ctx":"La síntesis de la urea por Wöhler en 1828, a partir de una sal inorgánica, contradijo la idea de que los compuestos orgánicos solo podían formarse en los seres vivos.","q":"¿Qué muestra este hecho sobre la ciencia?","o":["Que un experimento bien hecho puede cambiar una idea aceptada durante mucho tiempo","Que las ideas aceptadas por muchos científicos nunca deben cuestionarse","Que la urea es un compuesto inorgánico y por eso se pudo sintetizar","Que los compuestos orgánicos solo se forman dentro de los seres vivos"]},{"t":"rxn_derivados","c":"ind","af":"N4","ctx":"Se siguió la esterificación del ácido acético con etanol, en dos montajes iguales: uno con unas gotas de ácido sulfúrico y otro sin él.","q":"¿Qué papel cumple el ácido sulfúrico según la gráfica?","o":["Acelera la reacción: con él se llega antes a un mayor rendimiento","Es un reactivo que se consume y por eso sube el rendimiento","No tiene efecto: las dos curvas suben","Detiene la reacción cuando llega a 67 %"],"exp":"Con ácido sulfúrico se llega a 67 % en 50 minutos; sin él, solo a 22 %. El ácido es un catalizador: acelera la reacción y no se consume. La curva no se detiene en 67 %: es el último dato medido.","graf":{"tipo":"lin","x":["0","10","20","30","40","50"],"series":[{"n":"Con ácido","y":[0,20,40,55,65,67]},{"n":"Sin ácido","y":[0,5,10,15,19,22]}],"ex":"Tiempo (min)","ey":"Rendimiento (%)"}}];
